import { appLogger } from '../logger/AppLogger';

export type EventCallback<TPayload = any> = (payload: TPayload) => void;

export interface EventSubscription {
  unsubscribe: () => void;
}

/**
 * Standard Cross-Feature System Events
 */
export const APP_EVENTS = {
  // Authentication & Session
  AUTH_LOGGED_IN: 'auth:logged_in',
  AUTH_LOGGED_OUT: 'auth:logged_out',
  AUTH_SESSION_EXPIRED: 'auth:session_expired',

  // Loan Origination
  LOAN_SUBMITTED: 'loan:submitted',
  LOAN_STATUS_CHANGED: 'loan:status_changed',

  // Customer Management
  CUSTOMER_REGISTERED: 'customer:registered',
  CUSTOMER_CBS_SYNCED: 'customer:cbs_synced',

  // Notifications & Alerts
  NOTIFICATION_RECEIVED: 'notification:received',
  NOTIFICATION_BADGE_UPDATED: 'notification:badge_updated',

  // Offline Synchronization
  SYNC_STARTED: 'sync:started',
  SYNC_PROGRESS: 'sync:progress',
  SYNC_COMPLETED: 'sync:completed',

  // Global Native Plugin / System Events
  NETWORK_STRENGTH_CHANGED: 'system:network_strength_changed',
  USER_INACTIVITY: 'system:user_inactivity',
  APP_LIFECYCLE_CHANGED: 'system:app_lifecycle_changed',
  THEME_MODE_CHANGED: 'system:theme_mode_changed',
  BIOMETRIC_CHANGED: 'system:biometric_changed',
  SCREEN_RECORDING_CHANGED: 'system:screen_recording_changed',
} as const;

export type AppEventType = (typeof APP_EVENTS)[keyof typeof APP_EVENTS] | string;

/**
 * Enterprise Application Event Bus (`AppEventBus`)
 *
 * Provides decoupled, type-safe publish/subscribe messaging across
 * independent Remote Micro-Frontends without establishing direct code dependencies.
 */
export class AppEventBus {
  private static instance: AppEventBus;
  private listeners: Map<string, Set<EventCallback>> = new Map();

  public static getInstance(): AppEventBus {
    if (!AppEventBus.instance) {
      AppEventBus.instance = new AppEventBus();
    }
    return AppEventBus.instance;
  }

  /**
   * Subscribes to an application event.
   * Returns an object with an `unsubscribe` method to prevent memory leaks.
   */
  public subscribe<TPayload = any>(
    event: AppEventType,
    callback: EventCallback<TPayload>
  ): EventSubscription {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }

    const set = this.listeners.get(event)!;
    set.add(callback as EventCallback);

    return {
      unsubscribe: () => {
        set.delete(callback as EventCallback);
        if (set.size === 0) {
          this.listeners.delete(event);
        }
      },
    };
  }

  /**
   * Publishes an event to all active subscribers.
   */
  public publish<TPayload = any>(event: AppEventType, payload?: TPayload): void {
    const set = this.listeners.get(event);
    if (!set || set.size === 0) {
      return;
    }

    appLogger.d('AppEventBus', `📢 [EVENT PUBLISHED] ${event}`, payload);

    for (const cb of Array.from(set)) {
      try {
        cb(payload);
      } catch (err) {
        appLogger.e('AppEventBus', `❌ Error executing subscriber for event [${event}]`, err);
      }
    }
  }

  /**
   * Clears all listeners for an event, or all events if omitted.
   */
  public clear(event?: AppEventType): void {
    if (event) {
      this.listeners.delete(event);
    } else {
      this.listeners.clear();
    }
  }

  public getListenerCount(event: AppEventType): number {
    return this.listeners.get(event)?.size ?? 0;
  }
}

export const defaultAppEventBus = AppEventBus.getInstance();
