/**
 * Document Export & CSV Generation Utilities
 *
 * Formats loan repayment schedules, debtor summaries, and underwriting reports
 * into standard CSV files suitable for external sharing and printing.
 */

export interface CsvColumn<T = any> {
  header: string;
  key: keyof T | ((row: T) => string | number | null | undefined);
}

/**
 * Escapes values according to RFC 4180 CSV specifications.
 */
function escapeCsvValue(val: any): string {
  if (val === null || val === undefined) return '';
  const str = String(val);
  if (str.includes(',') || str.includes('"') || str.includes('\n') || str.includes('\r')) {
    return `"${str.replace(/"/g, '""')}"`;
  }
  return str;
}

/**
 * Converts an array of objects to a formatted CSV string with UTF-8 BOM.
 */
export function generateCsv<TRow = any>(
  columns: CsvColumn<TRow>[],
  rows: TRow[],
  includeUtf8Bom: boolean = true
): string {
  const headerLine = columns.map((c) => escapeCsvValue(c.header)).join(',');
  const rowLines = rows.map((row) =>
    columns
      .map((col) => {
        const val = typeof col.key === 'function' ? col.key(row) : row[col.key];
        return escapeCsvValue(val);
      })
      .join(',')
  );

  const csvContent = [headerLine, ...rowLines].join('\r\n');
  return includeUtf8Bom ? `\uFEFF${csvContent}` : csvContent;
}

/**
 * Formats a loan amortization schedule into CSV lines.
 */
export interface ScheduleEntry {
  period: number;
  paymentDate: string;
  principal: number;
  interest: number;
  totalPayment: number;
  remainingBalance: number;
}

export function exportAmortizationScheduleCsv(schedule: ScheduleEntry[]): string {
  const columns: CsvColumn<ScheduleEntry>[] = [
    { header: 'No.', key: 'period' },
    { header: 'Payment Date', key: 'paymentDate' },
    { header: 'Principal Amount', key: 'principal' },
    { header: 'Interest Amount', key: 'interest' },
    { header: 'Total Installment', key: 'totalPayment' },
    { header: 'Remaining Balance', key: 'remainingBalance' },
  ];
  return generateCsv(columns, schedule);
}
