/**
 * DocumentUploadUtil: Utility for loan application document checklist management,
 * multi-photo batch processing, file size/format constraints, and MIME validation.
 * Matches DOC100-DOC300 document inventories from Lotte Finance (DL1/DL3/LFVN).
 */

export interface LoanDocumentItem {
  docCode: string; // e.g. DOC100, DOC101, DOC84
  docCategory: 'LEGAL' | 'INCOME' | 'COLLATERAL' | 'CONTRACT' | 'OTHER';
  docName: string;
  isMandatory: boolean;
  uploadedFiles: UploadedAttachment[];
  maxFilesAllowed?: number;
  minFilesRequired?: number;
}

export interface UploadedAttachment {
  id: string;
  fileName: string;
  fileSize: number; // in bytes
  mimeType: string;
  uri: string;
  uploadedAt: string;
}

export class DocumentUploadUtil {
  public static readonly MAX_FILE_SIZE_BYTES = 10 * 1024 * 1024; // 10MB per file
  public static readonly ALLOWED_MIME_TYPES = [
    'image/jpeg',
    'image/png',
    'image/webp',
    'application/pdf',
  ];

  /**
   * Validates an uploaded file's size and MIME type.
   */
  public static validateFile(file: {
    fileName: string;
    fileSize: number;
    mimeType: string;
  }): { valid: boolean; error?: string } {
    if (!file) return { valid: false, error: 'File data is missing.' };

    if (file.fileSize > this.MAX_FILE_SIZE_BYTES) {
      const maxMb = Math.round(this.MAX_FILE_SIZE_BYTES / (1024 * 1024));
      return {
        valid: false,
        error: `File "${file.fileName}" exceeds the maximum allowed size of ${maxMb}MB.`,
      };
    }

    if (!this.ALLOWED_MIME_TYPES.includes(file.mimeType.toLowerCase())) {
      return {
        valid: false,
        error: `File format "${file.mimeType}" is not supported. Please upload JPG, PNG, or PDF.`,
      };
    }

    return { valid: true };
  }

  /**
   * Formats file size in readable units (KB, MB).
   */
  public static formatFileSize(bytes: number): string {
    if (bytes <= 0) return '0 B';
    const units = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(1024));
    const size = (bytes / Math.pow(1024, i)).toFixed(1);
    return `${size} ${units[i]}`;
  }

  /**
   * Standardizes core banking document codes from Lotte Finance:
   * - DOC100: National ID (Mặt trước CCCD)
   * - DOC101: National ID (Mặt sau CCCD)
   * - DOC102: Portrait Selfie (Ảnh chụp khuôn mặt)
   * - DOC105: Family Register / CT07 (Sổ hộ khẩu / Xác nhận cư trú)
   * - DOC110: Labor Contract (Hợp đồng lao động)
   * - DOC117: Bank Account Statement 3/6 Months (Sao kê tài khoản lương)
   * - DOC120: Social Insurance BHXH (Bảo hiểm xã hội)
   * - DOC84: Signed Loan Contract (Hợp đồng cho vay đã ký)
   */
  public static getStandardChecklist(productType: 'CASH_LOAN' | 'AUTO_LOAN'): LoanDocumentItem[] {
    const baseList: LoanDocumentItem[] = [
      {
        docCode: 'DOC100',
        docCategory: 'LEGAL',
        docName: 'National ID Front (Mặt trước CCCD)',
        isMandatory: true,
        minFilesRequired: 1,
        maxFilesAllowed: 1,
        uploadedFiles: [],
      },
      {
        docCode: 'DOC101',
        docCategory: 'LEGAL',
        docName: 'National ID Back (Mặt sau CCCD)',
        isMandatory: true,
        minFilesRequired: 1,
        maxFilesAllowed: 1,
        uploadedFiles: [],
      },
      {
        docCode: 'DOC102',
        docCategory: 'LEGAL',
        docName: 'Face Portrait Photo (Ảnh chụp chân dung)',
        isMandatory: true,
        minFilesRequired: 1,
        maxFilesAllowed: 1,
        uploadedFiles: [],
      },
      {
        docCode: 'DOC117',
        docCategory: 'INCOME',
        docName: 'Bank Salary Statement 3 Months (Sao kê lương)',
        isMandatory: true,
        minFilesRequired: 1,
        maxFilesAllowed: 10,
        uploadedFiles: [],
      },
    ];

    if (productType === 'AUTO_LOAN') {
      baseList.push(
        {
          docCode: 'DOC201',
          docCategory: 'COLLATERAL',
          docName: 'Car Sales Contract / Deposit Slip (Hợp đồng mua bán / Đặt cọc)',
          isMandatory: true,
          minFilesRequired: 1,
          maxFilesAllowed: 5,
          uploadedFiles: [],
        },
        {
          docCode: 'DOC202',
          docCategory: 'COLLATERAL',
          docName: 'Showroom VAT Invoice (Hóa đơn VAT)',
          isMandatory: true,
          minFilesRequired: 1,
          maxFilesAllowed: 3,
          uploadedFiles: [],
        }
      );
    }

    return baseList;
  }

  /**
   * Verifies if all mandatory documents in a checklist have been completed.
   */
  public static verifyChecklistCompletion(checklist: LoanDocumentItem[]): {
    isComplete: boolean;
    missingDocCodes: string[];
    missingDocNames: string[];
  } {
    const missingDocCodes: string[] = [];
    const missingDocNames: string[] = [];

    for (const item of checklist) {
      if (item.isMandatory) {
        const minReq = item.minFilesRequired ?? 1;
        if (!item.uploadedFiles || item.uploadedFiles.length < minReq) {
          missingDocCodes.push(item.docCode);
          missingDocNames.push(item.docName);
        }
      }
    }

    return {
      isComplete: missingDocCodes.length === 0,
      missingDocCodes,
      missingDocNames,
    };
  }
}

