import {
  requestTrCode as nativeRequestTrCode,
  requestHttp as nativeRequestHttp,
  getNetworkInfo as nativeGetNetworkInfo,
  checkNetworkState as nativeCheckNetworkState,
  logger,
  type RequestTrCodeRequest,
  type RequestTrCodeResponse,
  type RequestTrCodeHeader,
  type RequestHttpRequest,
  type RequestHttpResponse,
} from 'react-native-bizmob-plugin';
import { appLogger } from '../logger/AppLogger';
import { AppConfig } from '../config/AppConfig';

// Import mock JSON payloads from @mfe/assets/mock/<TR_CODE>.json
import mockDAS0001 from '@mfe/assets/mock/DAS0001.json';
import mockDAS0002 from '@mfe/assets/mock/DAS0002.json';
import mockAPR0001 from '@mfe/assets/mock/APR0001.json';
import mockAPR0002 from '@mfe/assets/mock/APR0002.json';
import mockAPR0003 from '@mfe/assets/mock/APR0003.json';
import mockNTF0001 from '@mfe/assets/mock/NTF0001.json';
import mockNTF0002 from '@mfe/assets/mock/NTF0002.json';
import mockAUT0001 from '@mfe/assets/mock/AUT0001.json';
import mockAUT0002 from '@mfe/assets/mock/AUT0002.json';
import mockAUT0003 from '@mfe/assets/mock/AUT0003.json';
import mockLAU0001 from '@mfe/assets/mock/LAU0001.json';
import mockCIF0001 from '@mfe/assets/mock/CIF0001.json';
import mockCIF0002 from '@mfe/assets/mock/CIF0002.json';
import mockCIF0003 from '@mfe/assets/mock/CIF0003.json';
import mockSAL0001 from '@mfe/assets/mock/SAL0001.json';
import mockSAL0002 from '@mfe/assets/mock/SAL0002.json';
import mockSAL0003 from '@mfe/assets/mock/SAL0003.json';
import mockUSC00000I02 from '@mfe/assets/mock/USC00000I02.json';

/**
 * Standard Transaction Codes (TR_CODE) for LOS domains.
 * Maps to mock files under `packages/assets/mock/<TR_CODE>.json` (or `assets/mock/<TR_CODE>.json`).
 */
export const TR_CODES = {
  // Dashboard & Debtor
  DASHBOARD_SUMMARY: 'DAS0001',
  DEBTOR_LIST: 'DAS0002',

  // Approval Request List & Detail
  APPROVAL_LIST: 'APR0001',
  APPROVAL_DETAIL: 'APR0002',
  APPROVAL_CANCEL_MODIFY: 'APR0003',

  // Notification List & Detail
  NOTIFICATION_LIST: 'NTF0001',
  NOTIFICATION_DETAIL: 'NTF0002',

  // Launch & Authentication
  LAUNCH_INIT: 'LAU0001',
  AUTH_LOGIN: 'AUT0001',
  AUTH_OTP_REQUEST: 'AUT0002',
  AUTH_OTP_VERIFY: 'AUT0003',

  // Customer (CIF)
  CUSTOMER_INQUIRY: 'CIF0001',
  CUSTOMER_REGISTER: 'CIF0002',
  CUSTOMER_CBS_SYNC: 'CIF0003',

  // Loan Origination (SAL)
  LOAN_APPLICATION_LIST: 'SAL0001',
  LOAN_APPLICATION_CREATE: 'SAL0002',
  LOAN_APPLICATION_STATUS_UPDATE: 'SAL0003',

  // Core Banking Sample Inquiry
  CORE_BANKING_INQUIRY: 'USC00000I02',
} as const;

export type TrCodeType = (typeof TR_CODES)[keyof typeof TR_CODES] | string;

export interface NetworkRequestOptions<TPayload = Record<string, any>> {
  /**
   * Transaction Code (e.g. 'DAS0001', 'APR0001', 'NTF0001').
   * When `useMock = true`, loads mock JSON from `assets/mock/<trCode>.json`.
   */
  trCode: TrCodeType;
  /**
   * Request body / payload sent to the server or used by mock handlers.
   */
  payload?: TPayload;
  /**
   * Whether to load mock data from `assets/mock/<TR_CODE>.json` instead of calling live network.
   * Defaults to the service's global `defaultUseMock` configuration (true by default in dev/mock mode).
   */
  useMock?: boolean;
  /**
   * Optional full endpoint URL override. Defaults to `${baseUrl}/${trCode}`.
   */
  url?: string;
  /**
   * HTTP method (default: 'POST').
   */
  method?: 'POST' | 'GET' | 'PUT' | 'DELETE';
  /**
   * Custom HTTP headers map.
   */
  headers?: Record<string, string>;
  /**
   * Custom bizMOB TR Code header overrides.
   */
  trHeader?: Partial<RequestTrCodeHeader>;
  /**
   * Connection & read timeout in milliseconds (default: 30000).
   */
  timeoutMs?: number;
  /**
   * If true (or cacheTTLMs is set), enables caching for successful responses.
   * Subsequent identical requests return the cached response without calling the server.
   */
  cache?: boolean;
  /**
   * Optional cache time-to-live in milliseconds.
   * If omitted or <= 0, cached entry persists until explicitly invalidated or evicted.
   */
  cacheTTLMs?: number;
  /**
   * If true, ignores any existing cache and forces a fresh network call,
   * updating the cache with the new response if `cache` is true.
   */
  forceRefresh?: boolean;
  /**
   * Optional custom cache key override. Defaults to auto-computed key based on method, trCode/url, and payload.
   */
  cacheKey?: string;
}

export interface CacheEntry<TData = any> {
  response: NetworkResponse<TData>;
  timestamp: number;
  ttlMs?: number;
}

export interface NetworkResponse<TData = any> {
  result: boolean;
  trCode: string;
  useMock: boolean;
  fromCache?: boolean;
  header?: RequestTrCodeHeader | { result: boolean; error_code: string; error_text: string };
  body: TData;
  errorCode?: string;
  errorMessage?: string;
}

export interface INetworkService {
  getDefaultUseMock(): boolean;
  setDefaultUseMock(useMock: boolean): void;
  setBaseUrl(baseUrl: string): void;
  getBaseUrl(): string;
  registerMockData<T = any>(trCode: string, mockPayload: T): void;
  loadMockAsset<T = any>(trCode: string): Promise<NetworkResponse<T>>;
  request<TData = any, TPayload = Record<string, any>>(
    options: NetworkRequestOptions<TPayload>
  ): Promise<NetworkResponse<TData>>;
  requestHttp<TData = any, TBody = Record<string, any>>(
    params: RequestHttpRequest<TBody> & {
      useMock?: boolean;
      trCode?: string;
      cache?: boolean;
      cacheTTLMs?: number;
      forceRefresh?: boolean;
      cacheKey?: string;
    }
  ): Promise<RequestHttpResponse<TData> & { fromCache?: boolean }>;
  checkConnectivity(): Promise<{ isConnected: boolean; type: string }>;
  clearCache(cacheKeyOrPattern?: string): void;
  hasCachedResponse(cacheKey: string): boolean;
}

const BUILTIN_MOCK_REGISTRY: Record<string, any> = {
  DAS0001: mockDAS0001,
  DAS0002: mockDAS0002,
  APR0001: mockAPR0001,
  APR0002: mockAPR0002,
  APR0003: mockAPR0003,
  NTF0001: mockNTF0001,
  NTF0002: mockNTF0002,
  AUT0001: mockAUT0001,
  AUT0002: mockAUT0002,
  AUT0003: mockAUT0003,
  LAU0001: mockLAU0001,
  CIF0001: mockCIF0001,
  CIF0002: mockCIF0002,
  CIF0003: mockCIF0003,
  SAL0001: mockSAL0001,
  SAL0002: mockSAL0002,
  SAL0003: mockSAL0003,
  USC00000I02: mockUSC00000I02,
};

export interface NetworkPluginAdapter {
  requestTrCode: typeof nativeRequestTrCode;
  requestHttp: typeof nativeRequestHttp;
  getNetworkInfo: typeof nativeGetNetworkInfo;
  checkNetworkState: typeof nativeCheckNetworkState;
}

const defaultPluginAdapter: NetworkPluginAdapter = {
  requestTrCode: nativeRequestTrCode,
  requestHttp: nativeRequestHttp,
  getNetworkInfo: nativeGetNetworkInfo,
  checkNetworkState: nativeCheckNetworkState,
};

/**
 * Common Network Request Service (`NetworkService`)
 *
 * Wraps `react-native-bizmob-plugin` (`requestTrCode`, `requestHttp`, `checkNetworkState`)
 * and supports `useMock: boolean`.
 * When `useMock = true`, loads static mock JSON from `assets/mock/<TR_CODE>.json`.
 */
export class NetworkService implements INetworkService {
  private static instance: NetworkService;
  private defaultUseMock: boolean = AppConfig.enableMock;
  private baseUrl: string = AppConfig.apiBaseUrl;
  private customMockRegistry: Map<string, any> = new Map();
  private pluginAdapter: NetworkPluginAdapter;
  private memoryCache: Map<string, CacheEntry> = new Map();

  constructor(
    defaultUseMock: boolean = true,
    baseUrl?: string,
    pluginAdapter: NetworkPluginAdapter = defaultPluginAdapter
  ) {
    this.defaultUseMock = defaultUseMock;
    if (baseUrl) {
      this.baseUrl = baseUrl;
    }
    this.pluginAdapter = pluginAdapter;
  }

  public static getInstance(): NetworkService {
    if (!NetworkService.instance) {
      NetworkService.instance = new NetworkService(true);
    }
    return NetworkService.instance;
  }

  /**
   * Generates a stable deterministic cache key based on TR_CODE or URL, method, and payload.
   */
  public generateCacheKey(
    identifier: string,
    method: string = 'POST',
    payload?: any
  ): string {
    const normIdentifier = identifier.trim().toUpperCase();
    const normMethod = method.toUpperCase();
    let payloadStr = '';
    if (payload !== undefined && payload !== null) {
      if (typeof payload === 'object') {
        try {
          const sortedObj = Object.keys(payload)
            .sort()
            .reduce((acc: any, key: string) => {
              acc[key] = payload[key];
              return acc;
            }, {});
          payloadStr = JSON.stringify(sortedObj);
        } catch {
          payloadStr = String(payload);
        }
      } else {
        payloadStr = String(payload);
      }
    }
    return `${normMethod}:${normIdentifier}${payloadStr ? `:${payloadStr}` : ''}`;
  }

  /**
   * Clears cached responses.
   * If a pattern or key is provided, clears entries matching that key or regex/prefix.
   * If omitted, clears all cached responses.
   */
  public clearCache(cacheKeyOrPattern?: string): void {
    if (!cacheKeyOrPattern) {
      this.memoryCache.clear();
      appLogger.d('NetworkService', '🧹 [CACHE CLEARED] All network cache cleared.');
      return;
    }

    const norm = cacheKeyOrPattern.trim();
    for (const key of Array.from(this.memoryCache.keys())) {
      if (key === norm || key.includes(norm)) {
        this.memoryCache.delete(key);
        appLogger.d('NetworkService', `🧹 [CACHE CLEARED] Key cleared: ${key}`);
      }
    }
  }

  /**
   * Checks if an active, unexpired cached response exists for a cache key.
   */
  public hasCachedResponse(cacheKey: string): boolean {
    const entry = this.memoryCache.get(cacheKey);
    if (!entry) return false;
    if (entry.ttlMs && entry.ttlMs > 0) {
      const isExpired = Date.now() - entry.timestamp > entry.ttlMs;
      if (isExpired) {
        this.memoryCache.delete(cacheKey);
        return false;
      }
    }
    return true;
  }

  /**
   * Retrieves an active cache entry if present and valid.
   */
  private getValidCachedResponse<TData = any>(
    cacheKey: string
  ): NetworkResponse<TData> | null {
    const entry = this.memoryCache.get(cacheKey);
    if (!entry) return null;

    if (entry.ttlMs && entry.ttlMs > 0) {
      const age = Date.now() - entry.timestamp;
      if (age > entry.ttlMs) {
        this.memoryCache.delete(cacheKey);
        appLogger.d('NetworkService', `⌛ [CACHE EXPIRED] Key: ${cacheKey} (Age: ${age}ms > TTL: ${entry.ttlMs}ms)`);
        return null;
      }
    }

    // Clone response body to prevent downstream mutations in caller code
    const clonedBody =
      entry.response.body !== undefined && entry.response.body !== null
        ? JSON.parse(JSON.stringify(entry.response.body))
        : entry.response.body;

    return {
      ...entry.response,
      body: clonedBody,
      fromCache: true,
    };
  }

  /**
   * Stores a successful response in the in-memory cache.
   */
  private storeInCache<TData = any>(
    cacheKey: string,
    response: NetworkResponse<TData>,
    ttlMs?: number
  ): void {
    // Only cache successful responses
    if (!response.result) return;

    this.memoryCache.set(cacheKey, {
      response: {
        ...response,
        fromCache: false,
      },
      timestamp: Date.now(),
      ttlMs,
    });
    appLogger.d('NetworkService', `💾 [CACHE SAVED] Key: ${cacheKey}${ttlMs ? ` (TTL: ${ttlMs}ms)` : ''}`);
  }

  public getDefaultUseMock(): boolean {
    return this.defaultUseMock;
  }

  public setDefaultUseMock(useMock: boolean): void {
    this.defaultUseMock = useMock;
  }

  public getBaseUrl(): string {
    return this.baseUrl;
  }

  public setBaseUrl(baseUrl: string): void {
    this.baseUrl = baseUrl.replace(/\/+$/, '');
  }

  public registerMockData<T = any>(trCode: string, mockPayload: T): void {
    this.customMockRegistry.set(trCode.toUpperCase(), mockPayload);
  }

  /**
   * Resolves `assets/mock/<TR_CODE>.json` from bundled mock registry.
   */
  public async loadMockAsset<T = any>(trCode: string): Promise<NetworkResponse<T>> {
    const normalizedCode = trCode.trim().toUpperCase();
    appLogger.d('NetworkService', `📦 [MOCK REQUEST] TR_CODE: ${normalizedCode} -> Loading from assets/mock/${normalizedCode}.json`);
    const rawMock =
      this.customMockRegistry.get(normalizedCode) ??
      BUILTIN_MOCK_REGISTRY[normalizedCode];

    if (!rawMock) {
      appLogger.w('NetworkService', `⚠️ [MOCK NOT FOUND] assets/mock/${normalizedCode}.json does not exist.`);
      return {
        result: false,
        trCode: normalizedCode,
        useMock: true,
        header: {
          result: false,
          error_code: 'MOCK_NOT_FOUND',
          error_text: `Mock file assets/mock/${normalizedCode}.json was not found.`,
        },
        body: null as unknown as T,
        errorCode: 'MOCK_NOT_FOUND',
        errorMessage: `Mock file assets/mock/${normalizedCode}.json was not found.`,
      };
    }

    // Clone to avoid mutating static JSON imports in memory across requests
    const cloned = JSON.parse(JSON.stringify(rawMock));
    const header = cloned.header || {
      result: true,
      error_code: '0000',
      error_text: 'OK',
      serviceId: normalizedCode,
    };
    const isSuccess = header.result !== false && header.messageInfo?.result !== false;
    const bodyData = (cloned.body !== undefined ? cloned.body : cloned.payload !== undefined ? cloned.payload : cloned) as T;

    appLogger.i('NetworkService', `✅ [MOCK RESPONSE] TR_CODE: ${normalizedCode}`, {
      result: isSuccess,
      header,
      body: bodyData,
    });

    return {
      result: isSuccess,
      trCode: normalizedCode,
      useMock: true,
      header,
      body: bodyData,
      errorCode: isSuccess ? undefined : header.error_code || header.messageInfo?.code,
      errorMessage: isSuccess ? undefined : header.error_text || header.messageInfo?.message,
    };
  }

  /**
   * Executes a network request by TR_CODE.
   * - If `useMock === true` (or `defaultUseMock` when `useMock` is omitted), loads `assets/mock/<TR_CODE>.json`.
   * - If `useMock === false`, executes native `requestTrCode` via `react-native-bizmob-plugin`.
   */
  public async request<TData = any, TPayload = Record<string, any>>(
    options: NetworkRequestOptions<TPayload>
  ): Promise<NetworkResponse<TData>> {
    const {
      trCode,
      payload,
      useMock = this.defaultUseMock,
      url,
      method = 'POST',
      headers,
      trHeader,
      timeoutMs = 30000,
      cache = false,
      cacheTTLMs,
      forceRefresh = false,
      cacheKey: customCacheKey,
    } = options;

    const normalizedTrCode = trCode.trim().toUpperCase();
    const shouldCache = cache || (cacheTTLMs !== undefined && cacheTTLMs > 0);
    const effectiveCacheKey =
      customCacheKey || this.generateCacheKey(url || normalizedTrCode, method, payload);

    // 1. Check in-memory cache if caching enabled and not forcing fresh call
    if (shouldCache && !forceRefresh) {
      const cached = this.getValidCachedResponse<TData>(effectiveCacheKey);
      if (cached) {
        appLogger.i(
          'NetworkService',
          `⚡ [CACHE HIT] TR_CODE: ${normalizedTrCode} (Key: ${effectiveCacheKey}) -> Returning cached response without network request`
        );
        return cached;
      }
    }

    if (useMock) {
      const mockResult = await this.loadMockAsset<TData>(normalizedTrCode);
      if (shouldCache && mockResult.result) {
        this.storeInCache(effectiveCacheKey, mockResult, cacheTTLMs);
      }
      return mockResult;
    }

    const targetUrl = url || `${this.baseUrl}/${normalizedTrCode}`;
    const requestHeader: Partial<RequestTrCodeHeader> = {
      serviceId: normalizedTrCode,
      channelTypeCode: 'LOS_MOBILE',
      ...trHeader,
    };

    const trRequest: RequestTrCodeRequest<TPayload> = {
      url: targetUrl,
      method,
      'http-header': {
        'Content-Type': 'application/json',
        ...headers,
      },
      'http-body': payload,
      payload,
      header: requestHeader,
      'connection-timeout': timeoutMs,
      'read-timeout': timeoutMs,
    };

    appLogger.d(`[NetworkService] 🌐 [LIVE PLUGIN REQUEST] TR_CODE: ${normalizedTrCode}`, {
      url: targetUrl,
      method,
      header: requestHeader,
      payload,
      cache: shouldCache,
    });
    appLogger.i(`[NetworkService] Sending TR_CODE: ${normalizedTrCode} to ${targetUrl}`);

    try {
      const response: RequestTrCodeResponse<TData> = await this.pluginAdapter.requestTrCode<TData, TPayload>(
        trRequest
      );

      const resHeader: any = response?.header;
      const isError =
        resHeader?.result === false ||
        resHeader?.messageInfo?.result === false;

      const bodyData = (
        response?.body !== undefined
          ? response.body
          : response?.payload !== undefined
          ? response.payload
          : response
      ) as TData;

      appLogger.d(`[NetworkService] 🌐 [LIVE PLUGIN RESPONSE] TR_CODE: ${normalizedTrCode}`, {
        isError,
        header: resHeader,
        body: bodyData,
      });

      const finalResponse: NetworkResponse<TData> = {
        result: !isError,
        trCode: normalizedTrCode,
        useMock: false,
        header: resHeader,
        body: bodyData,
        errorCode: isError
          ? resHeader?.error_code || resHeader?.messageInfo?.code || 'E500'
          : undefined,
        errorMessage: isError
          ? resHeader?.error_text || resHeader?.messageInfo?.message || 'Network transaction failed'
          : undefined,
      };

      if (shouldCache && finalResponse.result) {
        this.storeInCache(effectiveCacheKey, finalResponse, cacheTTLMs);
      }

      return finalResponse;
    } catch (error: any) {
      const errMsg = error?.message || 'Network request failed via bizMOB plugin';
      appLogger.e(`[NetworkService] ❌ [LIVE PLUGIN ERROR] TR_CODE: ${normalizedTrCode}`, error);
      return {
        result: false,
        trCode: normalizedTrCode,
        useMock: false,
        header: {
          result: false,
          error_code: 'E500',
          error_text: errMsg,
        },
        body: null as unknown as TData,
        errorCode: 'E500',
        errorMessage: errMsg,
      };
    }
  }

  /**
   * Executes a general HTTP REST request via `react-native-bizmob-plugin` (`requestHttp`).
   * If `useMock === true` and `trCode` is provided, resolves `assets/mock/<TR_CODE>.json`.
   */
  public async requestHttp<TData = any, TBody = Record<string, any>>(
    params: RequestHttpRequest<TBody> & {
      useMock?: boolean;
      trCode?: string;
      cache?: boolean;
      cacheTTLMs?: number;
      forceRefresh?: boolean;
      cacheKey?: string;
    }
  ): Promise<RequestHttpResponse<TData> & { fromCache?: boolean }> {
    const shouldUseMock = params.useMock ?? this.defaultUseMock;
    const shouldCache = params.cache || (params.cacheTTLMs !== undefined && params.cacheTTLMs > 0);
    const effectiveCacheKey =
      params.cacheKey ||
      this.generateCacheKey(
        params.url || params.trCode || 'HTTP',
        params.method || 'GET',
        params.body || params.params
      );

    if (shouldCache && !params.forceRefresh) {
      const cached = this.getValidCachedResponse<TData>(effectiveCacheKey);
      if (cached) {
        appLogger.i(
          'NetworkService',
          `⚡ [CACHE HIT HTTP] Key: ${effectiveCacheKey} -> Returning cached response without network request`
        );
        return {
          response_code: cached.result ? 200 : 500,
          response_data: cached.body,
          error_text: cached.errorMessage || '',
          fromCache: true,
        };
      }
    }

    if (shouldUseMock && params.trCode) {
      const mockRes = await this.loadMockAsset<TData>(params.trCode);
      const httpRes = {
        response_code: mockRes.result ? 200 : 404,
        response_data: mockRes.body,
        error_text: mockRes.errorMessage || '',
        fromCache: false,
      };
      if (shouldCache && mockRes.result) {
        this.storeInCache(effectiveCacheKey, mockRes, params.cacheTTLMs);
      }
      return httpRes;
    }

    const res = await this.pluginAdapter.requestHttp<TData, TBody>(params);
    if (shouldCache && res && res.response_code >= 200 && res.response_code < 300) {
      this.storeInCache(
        effectiveCacheKey,
        {
          result: true,
          trCode: params.trCode || 'HTTP',
          useMock: false,
          body: res.response_data,
        },
        params.cacheTTLMs
      );
    }

    return {
      ...res,
      fromCache: false,
    };
  }

  /**
   * Checks network connectivity state via `react-native-bizmob-plugin`.
   */
  public async checkConnectivity(): Promise<{ isConnected: boolean; type: string }> {
    try {
      const res: any = await this.pluginAdapter.checkNetworkState();
      const body = res?.body || res;
      if (body && typeof body.isConnected === 'boolean') {
        return {
          isConnected: body.isConnected,
          type: body.type || body.network_type || 'unknown',
        };
      }
      const infoRes: any = await this.pluginAdapter.getNetworkInfo();
      const infoBody = infoRes?.body || infoRes;
      return {
        isConnected: infoBody?.isConnected ?? true,
        type: infoBody?.type || 'wifi',
      };
    } catch {
      return { isConnected: true, type: 'wifi' };
    }
  }
}

export const defaultNetworkService = NetworkService.getInstance();
