import { Dimensions, Platform } from 'react-native';
import { appLogger } from '../logger/AppLogger';

export type TelemetryBreadcrumbType =
  | 'user_action'
  | 'navigation'
  | 'http'
  | 'system'
  | 'error';

export type TelemetryBreadcrumbCategory =
  | 'auth'
  | 'navigation'
  | 'file_upload'
  | 'network'
  | 'user_action'
  | 'warning'
  | 'hardware'
  | 'qr_parser'
  | 'database'
  | string;

export interface TelemetryDeviceInfo {
  deviceModel: string;
  osVersion: string;
  appFlavor?: string;
  ramUsage?: string;
  storageUsage?: string;
  freeDiskSpace?: string;
  cpuUsage?: string;
  battery?: string;
  isCharging?: boolean;
  network?: string;
  securityState?: string;
  screenResolution?: string;
  screenOrientation?: 'PORTRAIT' | 'LANDSCAPE';
  locale?: string;
}

export interface TelemetryBreadcrumb {
  id: string;
  timestamp: string;
  message: string;
  category: TelemetryBreadcrumbCategory;
  type: TelemetryBreadcrumbType;
}

export interface TelemetrySessionPayload {
  userId: string;
  deviceId: string;
  appId: string;
  device: TelemetryDeviceInfo;
}

export interface TelemetryBreadcrumbPayload {
  userId: string;
  deviceId: string;
  appId: string;
  breadcrumb: TelemetryBreadcrumb;
}

export interface CrashStackFrame {
  className: string;
  methodName: string;
  fileName: string;
  lineNumber: number;
  raw: string;
  isAppCode: boolean;
}

export interface CrashReportPayload {
  bundleId: string;
  versionName: string;
  versionCode: string;
  severity: 'FATAL' | 'NON_FATAL';
  exceptionClass: string;
  exceptionMessage: string;
  errorCode?: string;
  topAppFrame?: string;
  userId: string;
  deviceId: string;
  device: TelemetryDeviceInfo;
  breadcrumbs: TelemetryBreadcrumb[];
  stackTrace: CrashStackFrame[];
}

export interface TelemetryTransport {
  post: (url: string, body: unknown) => Promise<void>;
}

export interface TelemetryConfig {
  baseUrl: string;
  appId: string;
  versionName: string;
  versionCode: string;
  appFlavor: string;
  /** When true (default), logs structured telemetry payloads without sending HTTP requests. */
  logOnly: boolean;
  /** Maximum breadcrumbs retained in memory (ring buffer). */
  maxBreadcrumbs: number;
  /** Maximum queued events before oldest are dropped to protect memory/perf. */
  maxQueueSize: number;
}

interface QueuedTelemetryTask {
  endpoint: string;
  payload: unknown;
}

const DEFAULT_CONFIG: TelemetryConfig = {
  baseUrl: '',
  appId: 'mcnc.dbcs.losapp.sit',
  versionName: '1.0.0',
  versionCode: '10000',
  appFlavor: 'SIT_STAGING',
  logOnly: true,
  maxBreadcrumbs: 50,
  maxQueueSize: 100,
};

const defaultTransport: TelemetryTransport = {
  post: async (url: string, body: unknown) => {
    if (typeof fetch !== 'function') return;
    await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
    });
  },
};

function parseStackTrace(stack?: string): CrashStackFrame[] {
  if (!stack) return [];
  return stack
    .split('\n')
    .slice(1, 15)
    .map((line) => {
      const trimmed = line.trim();
      const match = trimmed.match(/at\s+(?:(.+?)\s+\()?(.+?):(\d+)(?::\d+)?\)?/);
      const methodName = match?.[1] || 'anonymous';
      const fileName = match?.[2] || 'unknown';
      const lineNumber = match?.[3] ? Number(match[3]) : 0;
      const isAppCode = !fileName.includes('node_modules');
      return {
        className: fileName.split('/').pop() || 'App',
        methodName,
        fileName,
        lineNumber,
        raw: trimmed,
        isAppCode,
      };
    });
}

/**
 * Lightweight, non-blocking User Activity Tracking & Crashlytics Telemetry Service.
 *
 * Matches the Crashlytics Postman API contract:
 * - POST /api/v1/telemetry/session
 * - POST /api/v1/telemetry/breadcrumb
 * - POST /api/v1/crash-reports
 *
 * Performance safeguards:
 * - Bounded in-memory breadcrumb ring buffer (`maxBreadcrumbs`)
 * - Bounded deferred async queue (`maxQueueSize`) flushed off the UI call stack
 * - Defaults to `logOnly: true` so payloads are logged cleanly via `appLogger` first
 */
export class UserActivityTelemetryService {
  private static instance: UserActivityTelemetryService;

  private config: TelemetryConfig;
  private transport: TelemetryTransport;
  private userId = 'anonymous';
  private deviceId = 'dev_unknown';
  private deviceInfo: TelemetryDeviceInfo;
  private breadcrumbs: TelemetryBreadcrumb[] = [];
  private queue: QueuedTelemetryTask[] = [];
  private isFlushing = false;
  private flushScheduled = false;
  private seq = 0;

  constructor(
    config?: Partial<TelemetryConfig>,
    transport: TelemetryTransport = defaultTransport
  ) {
    this.config = { ...DEFAULT_CONFIG, ...config };
    this.transport = transport;
    this.deviceInfo = this.collectDefaultDeviceInfo();
  }

  public static getInstance(): UserActivityTelemetryService {
    if (!UserActivityTelemetryService.instance) {
      UserActivityTelemetryService.instance = new UserActivityTelemetryService();
    }
    return UserActivityTelemetryService.instance;
  }

  public configure(partial: Partial<TelemetryConfig>): void {
    this.config = { ...this.config, ...partial };
  }

  public setUserContext(userId: string, deviceId?: string): void {
    this.userId = userId || 'anonymous';
    if (deviceId) {
      this.deviceId = deviceId;
    }
  }

  public getBreadcrumbs(): TelemetryBreadcrumb[] {
    return [...this.breadcrumbs];
  }

  public clearBreadcrumbs(): void {
    this.breadcrumbs = [];
  }

  /**
   * 1. POST /api/v1/telemetry/session
   */
  public initSession(
    userId: string,
    deviceId?: string,
    deviceOverride?: Partial<TelemetryDeviceInfo>
  ): TelemetrySessionPayload {
    this.setUserContext(userId, deviceId);
    this.deviceInfo = {
      ...this.collectDefaultDeviceInfo(),
      ...this.deviceInfo,
      ...deviceOverride,
    };

    const payload: TelemetrySessionPayload = {
      userId: this.userId,
      deviceId: this.deviceId,
      appId: this.config.appId,
      device: this.deviceInfo,
    };

    this.enqueue('/api/v1/telemetry/session', payload);
    return payload;
  }

  /**
   * 2. POST /api/v1/telemetry/breadcrumb
   */
  public trackBreadcrumb(
    message: string,
    category: TelemetryBreadcrumbCategory = 'user_action',
    type: TelemetryBreadcrumbType = 'user_action'
  ): TelemetryBreadcrumbPayload {
    this.seq += 1;
    const breadcrumb: TelemetryBreadcrumb = {
      id: `bc_${Date.now()}_${this.seq}`,
      timestamp: new Date().toISOString(),
      message,
      category,
      type,
    };

    // Bounded ring buffer (O(1) memory cap)
    this.breadcrumbs.push(breadcrumb);
    if (this.breadcrumbs.length > this.config.maxBreadcrumbs) {
      this.breadcrumbs.shift();
    }

    const payload: TelemetryBreadcrumbPayload = {
      userId: this.userId,
      deviceId: this.deviceId,
      appId: this.config.appId,
      breadcrumb,
    };

    this.enqueue('/api/v1/telemetry/breadcrumb', payload);
    return payload;
  }

  public trackNavigation(screenName: string, params?: Record<string, unknown>): TelemetryBreadcrumbPayload {
    const query = params && Object.keys(params).length > 0
      ? ` (${JSON.stringify(params)})`
      : '';
    return this.trackBreadcrumb(
      `Navigated to screen: ${screenName}${query}`,
      'navigation',
      'navigation'
    );
  }

  public trackUserAction(
    action: string,
    category: TelemetryBreadcrumbCategory = 'user_action'
  ): TelemetryBreadcrumbPayload {
    return this.trackBreadcrumb(action, category, 'user_action');
  }

  public trackHttp(
    method: string,
    url: string,
    statusCode: number,
    details?: string
  ): TelemetryBreadcrumbPayload {
    const suffix = details ? ` (${details})` : '';
    return this.trackBreadcrumb(
      `${method.toUpperCase()} ${url} responded ${statusCode}${suffix}`,
      statusCode >= 400 ? 'warning' : 'network',
      'http'
    );
  }

  /**
   * 3. POST /api/v1/crash-reports
   */
  public reportCrash(
    error: Error | string,
    options?: {
      severity?: 'FATAL' | 'NON_FATAL';
      errorCode?: string;
    }
  ): CrashReportPayload {
    const errObj = typeof error === 'string' ? new Error(error) : error;
    const frames = parseStackTrace(errObj.stack);
    const topAppFrame = frames.find((f) => f.isAppCode);

    const payload: CrashReportPayload = {
      bundleId: this.config.appId,
      versionName: this.config.versionName,
      versionCode: this.config.versionCode,
      severity: options?.severity || 'NON_FATAL',
      exceptionClass: errObj.name || 'Error',
      exceptionMessage: errObj.message || String(error),
      errorCode: options?.errorCode,
      topAppFrame: topAppFrame
        ? `${topAppFrame.fileName}:${topAppFrame.lineNumber}`
        : undefined,
      userId: this.userId,
      deviceId: this.deviceId,
      device: this.deviceInfo,
      breadcrumbs: this.getBreadcrumbs(),
      stackTrace: frames,
    };

    this.enqueue('/api/v1/crash-reports', payload);
    return payload;
  }

  /**
   * Flushes all queued telemetry events asynchronously without blocking the UI thread.
   */
  public async flush(): Promise<void> {
    if (this.isFlushing || this.queue.length === 0) return;
    this.isFlushing = true;

    try {
      while (this.queue.length > 0) {
        const task = this.queue.shift();
        if (!task) continue;

        if (this.config.logOnly || !this.config.baseUrl) {
          appLogger.i(
            'UserActivityTelemetry',
            `[LOG-ONLY] POST ${task.endpoint}`,
            task.payload
          );
          continue;
        }

        const url = `${this.config.baseUrl.replace(/\/$/, '')}${task.endpoint}`;
        try {
          await this.transport.post(url, task.payload);
        } catch (err) {
          appLogger.w(
            'UserActivityTelemetry',
            `Telemetry POST failed for ${task.endpoint}`,
            err
          );
        }
      }
    } finally {
      this.isFlushing = false;
    }
  }

  private enqueue(endpoint: string, payload: unknown): void {
    if (this.queue.length >= this.config.maxQueueSize) {
      this.queue.shift(); // Drop oldest event to guarantee bounded memory
    }
    this.queue.push({ endpoint, payload });

    if (!this.flushScheduled) {
      this.flushScheduled = true;
      setTimeout(() => {
        this.flushScheduled = false;
        this.flush().catch(() => {});
      }, 0);
    }
  }

  private collectDefaultDeviceInfo(): TelemetryDeviceInfo {
    const { width, height } = Dimensions.get('window');
    return {
      deviceModel: `${Platform.OS} device`,
      osVersion: `${Platform.OS} ${String(Platform.Version)}`,
      appFlavor: this.config.appFlavor,
      screenResolution: `${Math.round(width)}x${Math.round(height)}`,
      screenOrientation: height >= width ? 'PORTRAIT' : 'LANDSCAPE',
      locale: 'en_KH',
    };
  }
}

export const userActivityTelemetryService =
  UserActivityTelemetryService.getInstance();
