import {
  openSignaturePad as nativeOpenSignaturePad,
  type SignaturePadRequest,
  type SignaturePadResponse,
  type SignatureExportData,
} from 'react-native-bizmob-plugin';
import { appLogger } from '../logger/AppLogger';

export interface SignatureCaptureOptions {
  title?: string;
  guideText?: string;
  confirmButtonText?: string;
  cancelButtonText?: string;
  strokeColor?: string;
  strokeWidth?: number;
  orientation?: 'portrait' | 'landscape';
}

export interface CapturedSignatureResult {
  isConfirmed: boolean;
  base64Png?: string;
  svgPath?: string;
  width?: number;
  height?: number;
  timestamp: number;
}

export interface SignaturePluginAdapter {
  openSignaturePad: typeof nativeOpenSignaturePad;
}

const defaultAdapter: SignaturePluginAdapter = {
  openSignaturePad: nativeOpenSignaturePad,
};

/**
 * Digital E-Signature Service (`DigitalSignatureService`)
 *
 * Captures legally binding borrower, co-borrower, and guarantor signatures
 * on digital loan agreements and site visit acknowledgments.
 */
export class DigitalSignatureService {
  private static instance: DigitalSignatureService;
  private adapter: SignaturePluginAdapter;

  constructor(adapter: SignaturePluginAdapter = defaultAdapter) {
    this.adapter = adapter;
  }

  public static getInstance(): DigitalSignatureService {
    if (!DigitalSignatureService.instance) {
      DigitalSignatureService.instance = new DigitalSignatureService();
    }
    return DigitalSignatureService.instance;
  }

  /**
   * Prompts the native signature pad modal with vector Bézier curve smoothing.
   */
  public async captureSignature(
    options?: SignatureCaptureOptions
  ): Promise<CapturedSignatureResult> {
    const req: SignaturePadRequest = {
      title: options?.title || 'Borrower Signature',
      guideText: options?.guideText || 'Please sign inside the box below',
      confirmButtonText: options?.confirmButtonText || 'Confirm Signature',
      cancelButtonText: options?.cancelButtonText || 'Cancel',
      strokeColor: options?.strokeColor || '#000000',
      strokeWidth: options?.strokeWidth || 3,
      orientation: options?.orientation || 'portrait',
      exportPng: true,
      exportSvg: true,
      transparentBg: true,
    };

    try {
      const res: SignaturePadResponse = await this.adapter.openSignaturePad(req);

      if (res?.header?.result && res?.body?.action === 'confirmed' && res.body.signature) {
        const sig: SignatureExportData = res.body.signature;
        appLogger.i('DigitalSignatureService', '✍️ Signature successfully captured.');
        return {
          isConfirmed: true,
          base64Png: sig.base64Png || sig.base64,
          svgPath: sig.svgPath,
          width: sig.width,
          height: sig.height,
          timestamp: Date.now(),
        };
      }

      return { isConfirmed: false, timestamp: Date.now() };
    } catch (err) {
      appLogger.w('DigitalSignatureService', '⚠️ Signature capture cancelled or error:', err);
      return { isConfirmed: false, timestamp: Date.now() };
    }
  }
}

export const defaultDigitalSignatureService = DigitalSignatureService.getInstance();
