/**
 * Personally Identifiable Information (PII) Data Masking Utilities
 *
 * Implements standard banking data anonymization for:
 * - Cambodian NRIC / National ID Cards
 * - Phone numbers (Local 0XX and International +855)
 * - Bank Accounts & CBS Loan Numbers
 * - Email addresses
 * - Credit Card / Card numbers
 */

/**
 * Masks a Cambodian National ID or Passport Number.
 * Example: `010456789` -> `010****89`
 */
export function maskNationalId(id: string | null | undefined): string {
  if (!id) return '';
  const clean = id.trim();
  if (clean.length <= 4) return '*'.repeat(clean.length);

  const startVisible = 3;
  const endVisible = 2;
  const maskLength = clean.length - startVisible - endVisible;

  return (
    clean.slice(0, startVisible) +
    '*'.repeat(Math.max(2, maskLength)) +
    clean.slice(clean.length - endVisible)
  );
}

/**
 * Masks a phone number preserving prefix and terminal digits.
 * Example: `087123496` -> `087 **** 96`
 * Example: `+85587123496` -> `+855 87 **** 96`
 */
export function maskPhoneNumber(phone: string | null | undefined): string {
  if (!phone) return '';
  const clean = phone.replace(/[\s-]/g, '');

  if (clean.startsWith('+855')) {
    const local = clean.slice(4);
    if (local.length < 5) return clean;
    return `+855 ${local.slice(0, 2)} **** ${local.slice(-2)}`;
  }

  if (clean.length <= 6) return clean;
  return `${clean.slice(0, 3)} **** ${clean.slice(-2)}`;
}

export interface MaskAccountOptions {
  /** Visible digits at the beginning (default: 3) */
  visibleStart?: number;
  /** Visible digits at the end (default: 4) */
  visibleEnd?: number;
  /** Character to use for masking (default: '*') */
  maskChar?: string;
  /** Grouping delimiter or separator (e.g. '-' or ' ' or '') */
  separator?: string;
  /** Fixed number of mask chars instead of proportional (optional) */
  fixedMaskLength?: number;
}

/**
 * Masks bank account numbers or CBS loan contract numbers.
 * Examples:
 * - Default: `000100234567` -> `000-***-***-4567`
 * - Dot style: `maskAccountNumber('19034567890123', { maskChar: '•', separator: ' ' })` -> `190 ••••••• 0123`
 */
export function maskAccountNumber(
  accountNo: string | null | undefined,
  options: MaskAccountOptions = {}
): string {
  if (!accountNo) return '';
  const clean = accountNo.replace(/[\s-]/g, '');
  if (clean.length <= 4) return (options.maskChar || '*').repeat(Math.max(4, clean.length));

  const {
    visibleStart = 3,
    visibleEnd = 4,
    maskChar = '*',
    separator = '-',
    fixedMaskLength,
  } = options;

  if (clean.length <= visibleStart + visibleEnd) {
    return clean;
  }

  const prefix = clean.slice(0, visibleStart);
  const suffix = clean.slice(-visibleEnd);
  const middleLength = clean.length - visibleStart - visibleEnd;

  let maskedMiddle: string;
  if (fixedMaskLength !== undefined) {
    maskedMiddle = maskChar.repeat(fixedMaskLength);
  } else if (separator === '-') {
    // Standard CBS grouped format: e.g. 000-***-***-4567
    const half = Math.ceil(middleLength / 2);
    maskedMiddle = `${maskChar.repeat(half)}${separator}${maskChar.repeat(middleLength - half)}`;
  } else {
    maskedMiddle = maskChar.repeat(Math.max(4, middleLength));
  }

  return separator ? `${prefix}${separator}${maskedMiddle}${separator}${suffix}` : `${prefix}${maskedMiddle}${suffix}`;
}

/**
 * Masks an email address preserving first char and domain.
 * Example: `uy.socheat@gmail.com` -> `uy.***@gmail.com`
 */
export function maskEmail(email: string | null | undefined): string {
  if (!email || !email.includes('@')) return email || '';
  const [localPart, domain] = email.split('@');
  if (localPart.length <= 2) {
    return `${localPart.slice(0, 1)}***@${domain}`;
  }
  const prefix = localPart.slice(0, Math.min(3, Math.ceil(localPart.length / 2)));
  return `${prefix}***@${domain}`;
}

/**
 * Masks customer name in public logs or non-sensitive views.
 * Example: `Pang Phanna` -> `P*** P*****`
 */
export function maskCustomerName(name: string | null | undefined): string {
  if (!name) return '';
  return name
    .trim()
    .split(/\s+/)
    .map((word) => (word.length <= 1 ? word : `${word[0]}${'*'.repeat(word.length - 1)}`))
    .join(' ');
}
