/**
 * Enterprise Formatter & Validator Utility Suite for Banking, LOS & Digital Channel Apps.
 * Covers:
 * - Bank Account formatting & masking (IBAN, NAPAS, Core Banking)
 * - Phone Number formatting (+84, +855, domestic 0xxx, international E.164) & validation
 * - Email RFC 5322 regex validation & masking
 * - CCCD / Citizen ID / NRIC 9 & 12-digit checksums, birth year & century decoders
 * - Date formatting & validation (DD/MM/YYYY, YYYY-MM-DD, age calculation, leap years)
 * - Time formatting & validation (HH:mm, HH:mm:ss, 12h AM/PM, business hour checkers)
 */

export interface ValidationResult {
  isValid: boolean;
  error?: string;
  normalized?: string;
}

export interface CccdValidationDetail extends ValidationResult {
  gender?: 'MALE' | 'FEMALE';
  birthCentury?: number;
  birthYear?: number;
  provinceCode?: string;
  type?: 'CCCD_CHIP_12' | 'CMND_OLD_9' | 'PASSPORT' | 'NRIC_CAMBODIA';
}

export class ValidationFormatUtil {
  // --------------------------------------------------------------------------
  // 1. BANK ACCOUNT NUMBER FORMATTING & VALIDATION
  // --------------------------------------------------------------------------

  /**
   * Formats a bank account number into clean grouped chunks of 4 digits.
   * e.g., "19034567890123" -> "1903 4567 8901 23"
   */
  public static formatAccountNumber(accountNumber: string, chunkSize: number = 4): string {
    if (!accountNumber) return '';
    const clean = accountNumber.replace(/[^0-9A-Za-z]/g, '');
    const regex = new RegExp(`.{1,${chunkSize}}`, 'g');
    const matches = clean.match(regex);
    return matches ? matches.join(' ') : clean;
  }

  /**
   * Masks a bank account number showing only first 3 and last 4 digits.
   * Supports optional custom mask character (default: '•') and custom separator (default: ' ').
   * e.g., "19034567890123" -> "190 •••• •••• 0123"
   */
  public static maskAccountNumber(
    accountNumber: string,
    options: { maskChar?: string; separator?: string; visibleStart?: number; visibleEnd?: number } = {}
  ): string {
    if (!accountNumber) return '';
    const clean = accountNumber.replace(/[^0-9A-Za-z]/g, '');
    const { maskChar = '•', separator = ' ', visibleStart = 3, visibleEnd = 4 } = options;

    if (clean.length <= visibleStart + visibleEnd) return clean;

    const start = clean.slice(0, visibleStart);
    const end = clean.slice(-visibleEnd);
    const maskLen = clean.length - (visibleStart + visibleEnd);
    
    // Group masked characters in chunks of 4 if space separator is used
    if (separator === ' ' && maskLen >= 4) {
      const chunks = Math.ceil(maskLen / 4);
      const maskedChunks: string[] = [];
      let remaining = maskLen;
      for (let i = 0; i < chunks; i++) {
        const take = Math.min(4, remaining);
        maskedChunks.push(maskChar.repeat(take));
        remaining -= take;
      }
      return `${start}${separator}${maskedChunks.join(separator)}${separator}${end}`;
    }

    const maskedChars = maskChar.repeat(Math.max(4, maskLen));
    return separator ? `${start}${separator}${maskedChars}${separator}${end}` : `${start}${maskedChars}${end}`;
  }

  /**
   * Validates a bank account number (length between 6 and 24 alphanumeric digits).
   */
  public static validateAccountNumber(accountNumber: string): ValidationResult {
    if (!accountNumber || !accountNumber.trim()) {
      return { isValid: false, error: 'Account number is required' };
    }
    const clean = accountNumber.replace(/[\s-]/g, '');
    if (!/^[0-9A-Za-z]{6,24}$/.test(clean)) {
      return {
        isValid: false,
        error: 'Account number must be between 6 and 24 alphanumeric characters',
      };
    }
    return { isValid: true, normalized: clean.toUpperCase() };
  }

  // --------------------------------------------------------------------------
  // 2. PHONE NUMBER FORMATTING & VALIDATION (Vietnam +84, Cambodia +855, Int'l)
  // --------------------------------------------------------------------------

  /**
   * Sanitizes and normalizes phone number input:
   * - Strips non-digits except leading '+'
   * - Restricts domestic numbers to max 10 digits
   * - Restricts international numbers to max 15 digits (ITU-T E.164)
   */
  public static sanitizePhoneNumber(phone: string): string {
    if (!phone) return '';
    const hasPlus = phone.trim().startsWith('+');
    const digitsOnly = phone.replace(/\D/g, '');

    if (hasPlus) {
      return `+${digitsOnly.slice(0, 14)}`;
    }
    return digitsOnly.slice(0, 10);
  }

  /**
   * Formats a phone number into readable groups.
   * e.g. "0912345678" -> "0912 345 678"
   * e.g. "+84912345678" -> "+84 912 345 678"
   */
  public static formatPhoneNumber(phone: string): string {
    if (!phone) return '';
    const clean = this.sanitizePhoneNumber(phone);

    // International Vietnam format (+84)
    if (clean.startsWith('+84') && clean.length >= 11) {
      return `+84 ${clean.slice(3, 6)} ${clean.slice(6, 9)} ${clean.slice(9)}`;
    }
    // Domestic Vietnam (0xxx xxx xxx)
    if (clean.startsWith('0') && clean.length <= 10) {
      if (clean.length <= 4) return clean;
      if (clean.length <= 7) return `${clean.slice(0, 4)} ${clean.slice(4)}`;
      return `${clean.slice(0, 4)} ${clean.slice(4, 7)} ${clean.slice(7, 10)}`;
    }
    // Cambodia (+855)
    if (clean.startsWith('+855')) {
      return `+855 ${clean.slice(4, 6)} ${clean.slice(6, 9)} ${clean.slice(9)}`;
    }

    // Generic fallback grouping
    return clean.replace(/(\d{3,4})(?=\d)/g, '$1 ');
  }

  /**
   * Masks phone number showing first 3 and last 3 digits.
   * e.g. "0912345678" -> "091 ••• •678"
   */
  public static maskPhoneNumber(phone: string): string {
    if (!phone) return '';
    const clean = phone.replace(/[^0-9+]/g, '');
    if (clean.length < 8) return clean;
    const start = clean.slice(0, 3);
    const end = clean.slice(-3);
    const masked = '•'.repeat(clean.length - 6);
    return `${start} ${masked} ${end}`;
  }

  /**
   * Validates standard mobile phone number (Vietnam 10 digits starting with 03, 05, 07, 08, 09 or +84; Cambodia 9-10 digits).
   */
  public static validatePhoneNumber(phone: string): ValidationResult {
    if (!phone || !phone.trim()) {
      return { isValid: false, error: 'Phone number is required' };
    }
    const clean = phone.replace(/[\s.-]/g, '');

    // Vietnam domestic (10 digits: 03x, 05x, 07x, 08x, 09x)
    const vnDomesticRegex = /^0(3[2-9]|5[2689]|7[06-9]|8[1-9]|9[0-9])[0-9]{7}$/;
    if (vnDomesticRegex.test(clean)) {
      return { isValid: true, normalized: clean };
    }

    // Vietnam international (+84 followed by 9 digits)
    const vnIntlRegex = /^\+84(3[2-9]|5[2689]|7[06-9]|8[1-9]|9[0-9])[0-9]{7}$/;
    if (vnIntlRegex.test(clean)) {
      return { isValid: true, normalized: `0${clean.slice(3)}` };
    }

    // Cambodia (+855 followed by 8-9 digits, or local 0 followed by Cambodia operator prefixes: Smart 010/096/098/086, Cellcard 011/012/017/076, Metfone 097/088/071/060, etc.)
    const khRegex = /^(\+855[1-9][0-9]{7,8}|0(1[0-24-8]|6[06-9]|7[0-16-9]|8[5-9]|9[6-8])[0-9]{6})$/;
    if (khRegex.test(clean)) {
      return { isValid: true, normalized: clean };
    }

    // E.164 General international
    if (/^\+[1-9]\d{6,14}$/.test(clean)) {
      return { isValid: true, normalized: clean };
    }

    return {
      isValid: false,
      error: 'Please enter a valid 10-digit mobile phone number (e.g. 0912 345 678)',
    };
  }

  // --------------------------------------------------------------------------
  // 3. EMAIL VALIDATION & MASKING
  // --------------------------------------------------------------------------

  /**
   * Validates email address according to RFC 5322 standard.
   */
  public static validateEmail(email: string): ValidationResult {
    if (!email || !email.trim()) {
      return { isValid: false, error: 'Email address is required' };
    }
    const clean = email.trim();
    // Standard RFC 5322 regex
    const emailRegex = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/;

    if (!emailRegex.test(clean)) {
      return { isValid: false, error: 'Please enter a valid email address (e.g. user@domain.com)' };
    }
    return { isValid: true, normalized: clean.toLowerCase() };
  }

  /**
   * Masks email address for privacy display.
   * e.g. "nguyen.an@gmail.com" -> "n•••••n@gmail.com"
   */
  public static maskEmail(email: string): string {
    if (!email || !email.includes('@')) return email || '';
    const [name, domain] = email.split('@');
    if (name.length <= 2) {
      return `${name[0]}*@${domain}`;
    }
    const maskedName = `${name[0]}${'•'.repeat(name.length - 2)}${name[name.length - 1]}`;
    return `${maskedName}@${domain}`;
  }

  // --------------------------------------------------------------------------
  // 4. CCCD / CITIZEN ID / PASSPORT VALIDATION & DECODER
  // --------------------------------------------------------------------------

  /**
   * Formats a 12-digit CCCD into readable 3-3-6 format.
   * e.g. "001098012345" -> "001 098 012345"
   */
  public static formatCccd(cccd: string): string {
    if (!cccd) return '';
    const clean = cccd.replace(/\D/g, '');
    if (clean.length === 12) {
      return `${clean.slice(0, 3)} ${clean.slice(3, 6)} ${clean.slice(6)}`;
    }
    return clean;
  }

  /**
   * Validates Vietnamese 12-digit Chip CCCD, 9-digit CMND, or Passport with detailed metadata extraction.
   * Structure of 12-digit CCCD:
   * - Digits 1-3: Province code (001 to 096)
   * - Digit 4: Century & Gender code (0: 20th century Male, 1: Female, 2: 21st century Male, etc.)
   * - Digits 5-6: 2-digit birth year
   * - Digits 7-12: 6 random unique identifier digits
   */
  public static validateCccdOrId(idNumber: string): CccdValidationDetail {
    if (!idNumber || !idNumber.trim()) {
      return { isValid: false, error: 'Citizen ID / CCCD number is required' };
    }
    const clean = idNumber.trim().toUpperCase();

    // 1. 12-digit CCCD
    if (/^\d{12}$/.test(clean)) {
      const province = clean.slice(0, 3);
      const genderCentury = parseInt(clean[3], 10);
      const birthYearTwoDigits = parseInt(clean.slice(4, 6), 10);

      let century = 1900;
      let gender: 'MALE' | 'FEMALE' = 'MALE';

      switch (genderCentury) {
        case 0: // 20th century (1900-1999), Male
          century = 1900;
          gender = 'MALE';
          break;
        case 1: // 20th century, Female
          century = 1900;
          gender = 'FEMALE';
          break;
        case 2: // 21st century (2000-2099), Male
          century = 2000;
          gender = 'MALE';
          break;
        case 3: // 21st century, Female
          century = 2000;
          gender = 'FEMALE';
          break;
        case 4: // 22nd century (2100-2199), Male
          century = 2100;
          gender = 'MALE';
          break;
        case 5: // 22nd century, Female
          century = 2100;
          gender = 'FEMALE';
          break;
        default:
          return { isValid: false, error: 'Invalid century or gender digit in CCCD' };
      }

      const fullBirthYear = century + birthYearTwoDigits;
      const currentYear = new Date().getFullYear();

      if (fullBirthYear > currentYear) {
        return { isValid: false, error: 'Birth year in CCCD cannot be in the future' };
      }

      return {
        isValid: true,
        type: 'CCCD_CHIP_12',
        normalized: clean,
        gender,
        birthCentury: century,
        birthYear: fullBirthYear,
        provinceCode: province,
      };
    }

    // 2. 9-digit CMND
    if (/^\d{9}$/.test(clean)) {
      return {
        isValid: true,
        type: 'CMND_OLD_9',
        normalized: clean,
      };
    }

    // 3. International Passport (1 letter + 7-8 digits)
    if (/^[A-Z][0-9]{7,8}$/.test(clean)) {
      return {
        isValid: true,
        type: 'PASSPORT',
        normalized: clean,
      };
    }

    return {
      isValid: false,
      error: 'ID must be a 12-digit CCCD, 9-digit CMND, or valid Passport number',
    };
  }

  // --------------------------------------------------------------------------
  // 5. DATE FORMATTING & VALIDATION (DD/MM/YYYY, YYYY-MM-DD, Age)
  // --------------------------------------------------------------------------

  /**
   * Formats a Date object or ISO string to standard banking display (DD/MM/YYYY).
   */
  public static formatDate(dateInput: Date | string | number, delimiter: string = '/'): string {
    if (!dateInput) return '';
    const date = typeof dateInput === 'object' ? dateInput : new Date(dateInput);
    if (isNaN(date.getTime())) return '';

    const day = String(date.getDate()).padStart(2, '0');
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const year = date.getFullYear();

    return `${day}${delimiter}${month}${delimiter}${year}`;
  }

  /**
   * Formats a Date to standard API payload ISO date format (YYYY-MM-DD).
   */
  public static formatDateToIso(dateInput: Date | string): string {
    if (!dateInput) return '';
    const date = typeof dateInput === 'object' ? dateInput : new Date(dateInput);
    if (isNaN(date.getTime())) return '';

    const day = String(date.getDate()).padStart(2, '0');
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const year = date.getFullYear();

    return `${year}-${month}-${day}`;
  }

  /**
   * Validates date string in DD/MM/YYYY or YYYY-MM-DD format with real calendar checks (leap years, month bounds).
   */
  public static validateDate(dateStr: string): ValidationResult {
    if (!dateStr || !dateStr.trim()) {
      return { isValid: false, error: 'Date is required' };
    }
    const clean = dateStr.trim();
    let day = 0;
    let month = 0;
    let year = 0;

    if (clean.includes('/')) {
      const parts = clean.split('/');
      if (parts.length !== 3) return { isValid: false, error: 'Date must be in DD/MM/YYYY format' };
      day = parseInt(parts[0], 10);
      month = parseInt(parts[1], 10);
      year = parseInt(parts[2], 10);
    } else if (clean.includes('-')) {
      const parts = clean.split('-');
      if (parts.length !== 3) return { isValid: false, error: 'Date must be in YYYY-MM-DD format' };
      year = parseInt(parts[0], 10);
      month = parseInt(parts[1], 10);
      day = parseInt(parts[2], 10);
    } else {
      return { isValid: false, error: 'Date must use slash (/) or dash (-) delimiters' };
    }

    if (month < 1 || month > 12) {
      return { isValid: false, error: 'Month must be between 1 and 12' };
    }
    if (year < 1900 || year > 2100) {
      return { isValid: false, error: 'Year must be between 1900 and 2100' };
    }

    // Days per month check including leap years
    const daysInMonth = [31, (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0 ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    if (day < 1 || day > daysInMonth[month - 1]) {
      return { isValid: false, error: `Day must be between 1 and ${daysInMonth[month - 1]} for month ${month}` };
    }

    const isoStr = `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    return { isValid: true, normalized: isoStr };
  }

  // --------------------------------------------------------------------------
  // 6. TIME FORMATTING & VALIDATION (HH:mm, HH:mm:ss, 12h AM/PM)
  // --------------------------------------------------------------------------

  /**
   * Formats a Date object or time string to 24-hour (HH:mm) or 12-hour (hh:mm A) format.
   */
  public static formatTime(dateInput: Date | string, use12Hour: boolean = false): string {
    if (!dateInput) return '';
    const date = typeof dateInput === 'object' ? dateInput : new Date(dateInput);
    if (isNaN(date.getTime())) return '';

    let hours = date.getHours();
    const minutes = String(date.getMinutes()).padStart(2, '0');

    if (use12Hour) {
      const ampm = hours >= 12 ? 'PM' : 'AM';
      hours = hours % 12;
      hours = hours ? hours : 12; // 0 becomes 12
      return `${String(hours).padStart(2, '0')}:${minutes} ${ampm}`;
    }

    return `${String(hours).padStart(2, '0')}:${minutes}`;
  }

  /**
   * Validates time string in 24-hour format (HH:mm or HH:mm:ss).
   */
  public static validateTime(timeStr: string): ValidationResult {
    if (!timeStr || !timeStr.trim()) {
      return { isValid: false, error: 'Time is required' };
    }
    const clean = timeStr.trim();
    const match = clean.match(/^([01]?[0-9]|2[0-3]):([0-5][0-9])(:([0-5][0-9]))?$/);

    if (!match) {
      return { isValid: false, error: 'Time must be in 24-hour HH:mm format (e.g. 08:30 or 17:45)' };
    }

    const hours = String(parseInt(match[1], 10)).padStart(2, '0');
    const minutes = match[2];
    const seconds = match[4] ? `:${match[4]}` : '';

    return { isValid: true, normalized: `${hours}:${minutes}${seconds}` };
  }

  /**
   * Checks whether the given time falls within bank business hours (e.g., 08:00 to 17:30).
   */
  public static isWithinBusinessHours(
    timeStr: string,
    openTime: string = '08:00',
    closeTime: string = '17:30'
  ): boolean {
    const val = this.validateTime(timeStr);
    if (!val.isValid || !val.normalized) return false;

    const [h, m] = val.normalized.slice(0, 5).split(':').map(Number);
    const [openH, openM] = openTime.split(':').map(Number);
    const [closeH, closeM] = closeTime.split(':').map(Number);

    const currentMinutes = h * 60 + m;
    const openMinutes = openH * 60 + openM;
    const closeMinutes = closeH * 60 + closeM;

    return currentMinutes >= openMinutes && currentMinutes <= closeMinutes;
  }
}
