export interface LocalStorageAdapter {
  getItem: (key: string) => Promise<string | null> | string | null;
  setItem: (key: string, value: string) => Promise<void> | void;
  removeItem: (key: string) => Promise<void> | void;
}

// In-memory fallback adapter if MMKV/AsyncStorage is not yet bound
class InMemoryStorage implements LocalStorageAdapter {
  private memory = new Map<string, string>();
  async getItem(key: string) {
    return this.memory.get(key) ?? null;
  }
  async setItem(key: string, value: string) {
    this.memory.set(key, value);
  }
  async removeItem(key: string) {
    this.memory.delete(key);
  }
}

export class DraftStorage {
  private static storage: LocalStorageAdapter = new InMemoryStorage();
  private static readonly PREFIX = '@MFE_DRAFT_';

  public static setStorageAdapter(adapter: LocalStorageAdapter): void {
    this.storage = adapter;
  }

  public static async saveDraft<T>(draftKey: string, data: T): Promise<void> {
    try {
      const payload = JSON.stringify({
        updatedAt: Date.now(),
        data,
      });
      await this.storage.setItem(`${this.PREFIX}${draftKey}`, payload);
    } catch (e) {
      console.warn('Failed to save draft:', e);
    }
  }

  public static async getDraft<T>(draftKey: string): Promise<T | null> {
    try {
      const raw = await this.storage.getItem(`${this.PREFIX}${draftKey}`);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      return parsed.data as T;
    } catch {
      return null;
    }
  }

  public static async clearDraft(draftKey: string): Promise<void> {
    try {
      await this.storage.removeItem(`${this.PREFIX}${draftKey}`);
    } catch (e) {
      console.warn('Failed to clear draft:', e);
    }
  }
}

