import React from 'react';

/**
 * FullScreenAlert Options and Utility for Success / Failed / Warning / Info states.
 * Matching screenshot "Gửi thẩm định thành công" with optional animated or normal icons.
 */

export type FullScreenAlertType = 'success' | 'failed' | 'warning' | 'info';

export interface FullScreenAlertOptions {
  id?: string;
  type?: FullScreenAlertType;
  title: string;
  message?: string;
  /** Primary button label, default: 'Trở về trang chủ' for success, 'Thử lại' for failed */
  primaryButtonText?: string;
  onPrimaryPress?: () => void;
  /** Optional secondary button label, e.g. 'Đóng' or 'Hủy' */
  secondaryButtonText?: string;
  onSecondaryPress?: () => void;
  /**
   * Icon animation style:
   * - 'animated': Smooth pulse, rotation, and spring pop-in
   * - 'normal': Static crisp vector-like circular icon
   * Default: 'animated'
   */
  animation?: 'animated' | 'normal';
  /** Custom extra details node (e.g. Transaction ID, Application Code APL...) */
  customContent?: React.ReactNode;
  /** Accessible testID */
  testID?: string;
}

export type FullScreenAlertListener = (alert: FullScreenAlertOptions | null) => void;

class FullScreenAlertController {
  private listeners: Set<FullScreenAlertListener> = new Set();
  private currentAlert: FullScreenAlertOptions | null = null;

  public subscribe(listener: FullScreenAlertListener): () => void {
    this.listeners.add(listener);
    listener(this.currentAlert);
    return () => {
      this.listeners.delete(listener);
    };
  }

  /**
   * Display full screen alert modal.
   */
  public show(options: FullScreenAlertOptions): Promise<boolean> {
    return new Promise((resolve) => {
      this.currentAlert = {
        ...options,
        onPrimaryPress: () => {
          if (options.onPrimaryPress) {
            options.onPrimaryPress();
          }
          this.dismiss();
          resolve(true);
        },
        onSecondaryPress: () => {
          if (options.onSecondaryPress) {
            options.onSecondaryPress();
          }
          this.dismiss();
          resolve(false);
        },
      };
      this.emit(this.currentAlert);
    });
  }

  /**
   * Shortcut for success screen matching screenshot: "Gửi thẩm định thành công".
   */
  public success(
    title: string = 'Gửi thẩm định thành công',
    message: string = 'Hồ sơ đã được gửi thẩm định. Kết quả sẽ được thông báo ngay sau khi hoàn tất quá trình thẩm định.',
    options?: Partial<FullScreenAlertOptions>
  ): Promise<boolean> {
    return this.show({
      type: 'success',
      title,
      message,
      primaryButtonText: 'Trở về trang chủ',
      animation: 'animated',
      ...options,
    });
  }

  /**
   * Shortcut for failed screen: "Giao dịch thất bại" / "Thẩm định không thành công".
   */
  public failed(
    title: string = 'Giao dịch thất bại',
    message: string = 'Đã xảy ra lỗi trong quá trình xử lý. Vui lòng kiểm tra lại thông tin và thử lại.',
    options?: Partial<FullScreenAlertOptions>
  ): Promise<boolean> {
    return this.show({
      type: 'failed',
      title,
      message,
      primaryButtonText: 'Thử lại',
      secondaryButtonText: 'Đóng',
      animation: 'animated',
      ...options,
    });
  }

  /**
   * Shortcut for warning screen.
   */
  public warning(
    title: string,
    message: string,
    options?: Partial<FullScreenAlertOptions>
  ): Promise<boolean> {
    return this.show({
      type: 'warning',
      title,
      message,
      primaryButtonText: 'Xác nhận',
      animation: 'animated',
      ...options,
    });
  }

  /**
   * Dismiss the currently active full-screen alert.
   */
  public dismiss(): void {
    if (!this.currentAlert) return;
    this.currentAlert = null;
    this.emit(null);
  }

  public getState(): FullScreenAlertOptions | null {
    return this.currentAlert;
  }

  private emit(alert: FullScreenAlertOptions | null) {
    this.listeners.forEach((listener) => {
      try {
        listener(alert);
      } catch (err) {
        console.warn('[FullScreenAlertUtil] Listener error:', err);
      }
    });
  }
}

export const FullScreenAlertUtil = new FullScreenAlertController();
export const fullScreenAlertUtil = FullScreenAlertUtil;
