/**
 * CreditScoringCicUtil: Models Credit Information Center (CIC / PCB) scoring grades,
 * overdue loan classifications (Group 1 to Group 5), and underwriting policy checks.
 * Aligned with State Bank of Vietnam (SBV) and NBC credit risk classifications.
 */

export type CicDebtGroup =
  | 'GROUP_1_CURRENT' // Standard debt (Nợ đủ tiêu chuẩn - Overdue < 10 days)
  | 'GROUP_2_SPECIAL_MENTION' // Special mention (Nợ cần chú ý - Overdue 10 to 90 days)
  | 'GROUP_3_SUBSTANDARD' // Substandard (Nợ dưới tiêu chuẩn - Overdue 91 to 180 days)
  | 'GROUP_4_DOUBTFUL' // Doubtful (Nợ nghi ngờ - Overdue 181 to 360 days)
  | 'GROUP_5_LOSS'; // Bad debt / Loss (Nợ có khả năng mất vốn - Overdue > 360 days)

export interface CicReportSummary {
  cicScore: number; // 400 - 850
  debtGroup: CicDebtGroup;
  totalActiveContracts: number;
  totalOutstandingBalance: number;
  overdueDaysMax: number;
  creditCardUtilizationRate?: number; // e.g. 45%
  inquiriesLast3Months: number;
}

export interface UnderwritingCicDecision {
  isEligible: boolean;
  riskTier: 'PRIME' | 'STANDARD' | 'NEAR_PRIME' | 'SUBPRIME' | 'REJECT';
  reasons: string[];
  maxAllowableLoanMultiplier: number; // e.g. 10x monthly income
}

export class CreditScoringCicUtil {
  /**
   * Classifies debt group based on max overdue days according to central bank policy.
   */
  public static classifyDebtGroup(overdueDays: number): CicDebtGroup {
    if (overdueDays <= 9) return 'GROUP_1_CURRENT';
    if (overdueDays <= 90) return 'GROUP_2_SPECIAL_MENTION';
    if (overdueDays <= 180) return 'GROUP_3_SUBSTANDARD';
    if (overdueDays <= 360) return 'GROUP_4_DOUBTFUL';
    return 'GROUP_5_LOSS';
  }

  /**
   * Performs automated CIC credit risk evaluation.
   */
  public static evaluateCicReport(report: CicReportSummary): UnderwritingCicDecision {
    const reasons: string[] = [];

    // Critical rejection: Bad debt (Group 3, 4, 5)
    if (
      report.debtGroup === 'GROUP_3_SUBSTANDARD' ||
      report.debtGroup === 'GROUP_4_DOUBTFUL' ||
      report.debtGroup === 'GROUP_5_LOSS'
    ) {
      reasons.push(
        `Borrower has delinquent debt record (${report.debtGroup.replace('_', ' ')}). Auto-rejected by policy.`
      );
      return {
        isEligible: false,
        riskTier: 'REJECT',
        reasons,
        maxAllowableLoanMultiplier: 0,
      };
    }

    // High inquiries in last 3 months (> 5 inquiries indicates credit hunger)
    if (report.inquiriesLast3Months >= 6) {
      reasons.push(
        `Excessive credit inquiries in last 90 days (${report.inquiriesLast3Months} inquiries).`
      );
    }

    // Risk tier assignment based on CIC score
    let riskTier: 'PRIME' | 'STANDARD' | 'NEAR_PRIME' | 'SUBPRIME' = 'STANDARD';
    let multiplier = 8; // Default 8x monthly salary

    if (report.cicScore >= 720) {
      riskTier = 'PRIME';
      multiplier = 12;
    } else if (report.cicScore >= 650) {
      riskTier = 'STANDARD';
      multiplier = 8;
    } else if (report.cicScore >= 580) {
      riskTier = 'NEAR_PRIME';
      multiplier = 5;
    } else {
      riskTier = 'SUBPRIME';
      multiplier = 2;
    }

    if (report.debtGroup === 'GROUP_2_SPECIAL_MENTION') {
      reasons.push('Borrower has Group 2 historical debt; maximum exposure reduced by 50%.');
      multiplier = Math.round(multiplier * 0.5);
    }

    return {
      isEligible: true,
      riskTier,
      reasons,
      maxAllowableLoanMultiplier: multiplier,
    };
  }
}

