/**
 * Banking Deep-Link & URI Scheme Route Parser
 *
 * Maps deep links and push notification navigation payloads
 * directly to typed Micro-Frontend routes.
 *
 * Supported URI patterns:
 * - `losapp://loans/detail?id=2026BL001` -> Route: 'LoanDetail', params: { id: '2026BL001' }
 * - `losapp://notifications/detail?id=5` -> Route: 'NotificationDetail', params: { id: '5' }
 * - `losapp://dashboard` -> Route: 'Dashboard'
 * - `losapp://customer/cif?cifNo=10099` -> Route: 'CustomerDetail', params: { cifNo: '10099' }
 */

export interface ParsedDeepLink {
  isValid: boolean;
  rawUrl: string;
  scheme?: string;
  host?: string;
  path?: string;
  params: Record<string, string>;
  targetRoute?: string;
}

export function parseDeepLink(url: string | null | undefined): ParsedDeepLink {
  if (!url || typeof url !== 'string') {
    return { isValid: false, rawUrl: '', params: {} };
  }

  const clean = url.trim();
  const match = clean.match(/^([a-zA-Z0-9_-]+):\/\/([^/?#]+)([^?#]*)(?:\?([^#]*))?/);

  if (!match) {
    return { isValid: false, rawUrl: clean, params: {} };
  }

  const [, scheme, host, path, queryString] = match;
  const params: Record<string, string> = {};

  if (queryString) {
    const pairs = queryString.split('&');
    for (const pair of pairs) {
      const [k, v] = pair.split('=');
      if (k) {
        params[decodeURIComponent(k)] = decodeURIComponent(v || '');
      }
    }
  }

  // Route Mapping Dictionary
  let targetRoute = 'Dashboard';
  const fullPath = `${host}${path}`.toLowerCase();

  if (fullPath.includes('loan') && fullPath.includes('detail')) {
    targetRoute = 'LoanDetail';
  } else if (fullPath.includes('notification') && fullPath.includes('detail')) {
    targetRoute = 'NotificationDetail';
  } else if (fullPath.includes('customer') || fullPath.includes('cif')) {
    targetRoute = 'CustomerInquiry';
  } else if (fullPath.includes('approval')) {
    targetRoute = 'ApprovalDetail';
  }

  return {
    isValid: true,
    rawUrl: clean,
    scheme,
    host,
    path,
    params,
    targetRoute,
  };
}
