/**
 * CollateralUtil: Utility for loan collateral management, appraisal evaluation,
 * Loan-to-Value (LTV) limits, vehicle depreciation, and asset documentation requirements.
 * Aligned with Lotte Finance DL1 (Auto loan - Vay mua ô tô) and LFVN Secured Lending rules.
 */

export type CollateralCategory =
  | 'VEHICLE_NEW'
  | 'VEHICLE_USED'
  | 'REAL_ESTATE'
  | 'DEPOSIT_CERTIFICATE'
  | 'MACHINERY_EQUIPMENT';

export interface CollateralAsset {
  id?: string;
  category: CollateralCategory;
  assetName: string;
  marketPrice: number;
  appraisedValue?: number;
  forcedSaleValue?: number; // Haircut value (e.g. 80% of appraisal)
  valuationDate?: string;
  details?: {
    brand?: string;
    model?: string;
    trim?: string;
    manufactureYear?: number;
    vinNumber?: string; // Chassis number (Số khung)
    engineNumber?: string; // Engine number (Số máy)
    licensePlate?: string; // Biển số xe
    color?: string;
    mileageKm?: number;
  };
}

export interface LtvAssessmentResult {
  requestedAmount: number;
  collateralValue: number;
  ltvPercentage: number;
  maxAllowableLtv: number;
  isEligible: boolean;
  maxEligibleLoanAmount: number;
  shortfallAmount: number;
  riskTier: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
}

export class CollateralUtil {
  /**
   * Maximum allowable LTV by asset category according to banking policy:
   * - New Car (Ô tô mới): 85% LTV
   * - Used Car (Ô tô cũ): 70% LTV
   * - Real Estate (Bất động sản): 75% LTV
   * - Certificate of Deposit (Sổ tiết kiệm): 95% LTV
   * - Equipment / Machinery (Máy móc thiết bị): 60% LTV
   */
  public static readonly DEFAULT_MAX_LTV: Record<CollateralCategory, number> = {
    VEHICLE_NEW: 85,
    VEHICLE_USED: 70,
    REAL_ESTATE: 75,
    DEPOSIT_CERTIFICATE: 95,
    MACHINERY_EQUIPMENT: 60,
  };

  /**
   * Calculates LTV (Loan-to-Value) percentage:
   * LTV = (Loan Amount / Collateral Appraisal Value) * 100
   */
  public static calculateLtv(loanAmount: number, collateralValue: number): number {
    if (collateralValue <= 0) return 100;
    const ltv = (loanAmount / collateralValue) * 100;
    return Math.round(ltv * 100) / 100;
  }

  /**
   * Performs full LTV assessment against underwriting policy boundaries.
   */
  public static assessLtv(
    requestedAmount: number,
    collateralValue: number,
    category: CollateralCategory,
    customMaxLtv?: number
  ): LtvAssessmentResult {
    const maxLtv = customMaxLtv ?? this.DEFAULT_MAX_LTV[category] ?? 70;
    const ltvPercentage = this.calculateLtv(requestedAmount, collateralValue);
    const maxEligibleLoanAmount = Math.round(collateralValue * (maxLtv / 100));
    const shortfallAmount = Math.max(0, requestedAmount - maxEligibleLoanAmount);
    const isEligible = ltvPercentage <= maxLtv;

    let riskTier: 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL' = 'LOW';
    if (ltvPercentage > maxLtv) {
      riskTier = 'CRITICAL';
    } else if (ltvPercentage > maxLtv - 10) {
      riskTier = 'HIGH';
    } else if (ltvPercentage > maxLtv - 25) {
      riskTier = 'MEDIUM';
    }

    return {
      requestedAmount,
      collateralValue,
      ltvPercentage,
      maxAllowableLtv: maxLtv,
      isEligible,
      maxEligibleLoanAmount,
      shortfallAmount,
      riskTier,
    };
  }

  /**
   * Estimates vehicle depreciation based on age (manufacture year) for auto loans.
   * Depreciation rate standard:
   * - Year 1: 10%
   * - Year 2: 18%
   * - Year 3: 25%
   * - Year 4: 32%
   * - Year 5: 38%
   * - Year 6+: 45% + 5% per subsequent year (up to 75% max)
   */
  public static estimateVehicleValue(
    originalPrice: number,
    manufactureYear: number,
    currentYear: number = new Date().getFullYear()
  ): { estimatedValue: number; depreciationPercentage: number } {
    if (originalPrice <= 0) return { estimatedValue: 0, depreciationPercentage: 100 };

    const age = Math.max(0, currentYear - manufactureYear);
    let depRate = 0;

    if (age === 0) {
      depRate = 0; // Brand new
    } else if (age === 1) {
      depRate = 10;
    } else if (age === 2) {
      depRate = 18;
    } else if (age === 3) {
      depRate = 25;
    } else if (age === 4) {
      depRate = 32;
    } else if (age === 5) {
      depRate = 38;
    } else {
      depRate = Math.min(75, 45 + (age - 5) * 5);
    }

    const estimatedValue = Math.round(originalPrice * (1 - depRate / 100));
    return {
      estimatedValue,
      depreciationPercentage: depRate,
    };
  }

  /**
   * Validates Vehicle Identification Number (VIN / Số khung):
   * Standard 17 alphanumeric characters (excluding letters I, O, Q to avoid confusion with numbers 1, 0).
   */
  public static isValidVinNumber(vin: string): boolean {
    if (!vin) return false;
    const cleanVin = vin.trim().toUpperCase();
    return /^[A-HJ-NPR-Z0-9]{17}$/.test(cleanVin);
  }

  /**
   * Validates Vietnamese vehicle license plate format:
   * e.g., "30A-123.45", "51K-987.65", "29B-012.34".
   */
  public static isValidLicensePlate(plate: string): boolean {
    if (!plate) return false;
    const cleanPlate = plate.trim().toUpperCase().replace(/\s+/g, '');
    return /^[0-9]{2}[A-Z]{1,2}[-]?[0-9]{4,5}$|^[0-9]{2}[A-Z]{1,2}[-]?[0-9]{3}\.[0-9]{2}$/.test(
      cleanPlate
    );
  }

  /**
   * Returns list of required collateral documents (Danh mục hồ sơ TSĐB)
   * required by underwriting stage for disbursement approval.
   */
  public static getRequiredCollateralDocuments(category: CollateralCategory): {
    docCode: string;
    docName: string;
    isMandatory: boolean;
  }[] {
    switch (category) {
      case 'VEHICLE_NEW':
        return [
          { docCode: 'DOC_CAR_PURCHASE_CONTRACT', docName: 'Car Sales / Purchase Contract (Hợp đồng mua bán xe)', isMandatory: true },
          { docCode: 'DOC_CAR_VAT_INVOICE', docName: 'Official VAT Invoice from Showroom (Hóa đơn VAT)', isMandatory: true },
          { docCode: 'DOC_CAR_PAYMENT_RECEIPT', docName: 'Down Payment Receipt / Deposit Slip (Ủy nhiệm chi đặt cọc)', isMandatory: true },
          { docCode: 'DOC_CAR_INSURANCE_POLICY', docName: 'Comprehensive Vehicle Physical Insurance Policy (Bảo hiểm vật chất xe)', isMandatory: true },
        ];
      case 'VEHICLE_USED':
        return [
          { docCode: 'DOC_CAR_REGISTRATION', docName: 'Vehicle Registration Certificate (Cà vẹt xe / Giấy đăng ký xe)', isMandatory: true },
          { docCode: 'DOC_CAR_INSPECTION', docName: 'Vehicle Inspection Certificate (Sổ đăng kiểm)', isMandatory: true },
          { docCode: 'DOC_APPRAISAL_REPORT', docName: 'Independent Valuation Report (Chứng thư định giá xe)', isMandatory: true },
          { docCode: 'DOC_CAR_INSURANCE_POLICY', docName: 'Comprehensive Vehicle Physical Insurance Policy (Bảo hiểm vật chất xe)', isMandatory: true },
        ];
      case 'REAL_ESTATE':
        return [
          { docCode: 'DOC_LAND_CERTIFICATE', docName: 'Land Use Rights Certificate (Sổ đỏ / Sổ hồng)', isMandatory: true },
          { docCode: 'DOC_PROPERTY_VALUATION', docName: 'Independent Property Appraisal Report (Chứng thư thẩm định giá BĐS)', isMandatory: true },
          { docCode: 'DOC_MORTGAGE_REGISTRATION', docName: 'Secured Transaction Registration (Đăng ký giao dịch bảo đảm)', isMandatory: true },
        ];
      case 'DEPOSIT_CERTIFICATE':
        return [
          { docCode: 'DOC_SAVINGS_BOOK', docName: 'Original Certificate of Deposit / Savings Book (Sổ tiết kiệm)', isMandatory: true },
          { docCode: 'DOC_BANK_BLOCKAGE_NOTICE', docName: 'Bank Account Blockage Notice (Thông báo phong tỏa tài khoản)', isMandatory: true },
        ];
      default:
        return [
          { docCode: 'DOC_ASSET_OWNERSHIP', docName: 'Proof of Asset Ownership (Giấy tờ chứng minh quyền sở hữu)', isMandatory: true },
          { docCode: 'DOC_VALUATION_REPORT', docName: 'Valuation Report (Biên bản định giá tài sản)', isMandatory: true },
        ];
    }
  }
}

