/**
 * EkycValidator: Comprehensive validation utility for eKYC (electronic Know Your Customer),
 * National ID cards (CCCD 12-digit chip-based, CMND 9-digit, Cambodia NRIC),
 * Optical Character Recognition (OCR) confidence thresholds, and Face Liveness detection checks.
 * Aligned with Lotte Finance (DL1/DL2/DL3/LFVN) and DBCS LOS identity workflows.
 */

export interface OcrExtractedData {
  idNumber: string;
  fullName: string;
  dateOfBirth?: string; // DD/MM/YYYY
  gender?: 'MALE' | 'FEMALE' | 'OTHER';
  nationality?: string;
  residenceAddress?: string;
  issueDate?: string;
  expiryDate?: string;
  issuePlace?: string;
  confidenceScore?: number; // 0.0 - 1.0 (e.g. 0.85 = 85%)
}

export interface LivenessCheckResult {
  isLive: boolean;
  livenessScore: number; // 0.0 - 1.0
  passedChecks: ('BLINK' | 'SMILE' | 'HEAD_TURN' | 'PASSIVE_3D')[];
  failedChecks: string[];
  recommendation: 'APPROVE' | 'RETRY' | 'GO_TO_COUNTER';
}

export class EkycValidator {
  /**
   * Minimum OCR confidence required for automated straight-through processing (STP).
   * Anything below requires user manual review or branch counter inspection.
   */
  public static readonly MIN_OCR_CONFIDENCE = 0.75;
  public static readonly MIN_LIVENESS_SCORE = 0.80;

  /**
   * Validates Vietnamese CCCD (Căn cước công dân gắn chip):
   * Structure: 12 numeric digits:
   * - Digits 1-3: Province / City code (Mã tỉnh/thành phố, e.g. 001 = Hà Nội, 079 = TP.HCM)
   * - Digit 4: Century and Gender code (0 = Male 20th C., 1 = Female 20th C., 2 = Male 21st C., 3 = Female 21st C.)
   * - Digits 5-6: Year of birth (two last digits, e.g. 98 for 1998)
   * - Digits 7-12: Random unique sequential number (6 digits)
   */
  public static validateVietnameseCccd(idNumber: string): {
    valid: boolean;
    error?: string;
    details?: {
      provinceCode: string;
      gender: 'MALE' | 'FEMALE';
      century: number;
      birthYear: number;
    };
  } {
    if (!idNumber) {
      return { valid: false, error: 'Citizen ID number is required.' };
    }

    const clean = idNumber.trim();
    if (!/^\d{12}$/.test(clean)) {
      return {
        valid: false,
        error: 'Citizen ID (CCCD) must contain exactly 12 numeric digits.',
      };
    }

    const provinceCode = clean.slice(0, 3);
    const genderCenturyDigit = parseInt(clean[3], 10);
    const birthYearSuffix = parseInt(clean.slice(4, 6), 10);

    // Gender & century mapping
    let gender: 'MALE' | 'FEMALE' = 'MALE';
    let century = 20;

    if (genderCenturyDigit === 0 || genderCenturyDigit === 1) {
      century = 20; // 1900-1999
      gender = genderCenturyDigit === 0 ? 'MALE' : 'FEMALE';
    } else if (genderCenturyDigit === 2 || genderCenturyDigit === 3) {
      century = 21; // 2000-2099
      gender = genderCenturyDigit === 2 ? 'MALE' : 'FEMALE';
    } else if (genderCenturyDigit === 4 || genderCenturyDigit === 5) {
      century = 22; // 2100-2199
      gender = genderCenturyDigit === 4 ? 'MALE' : 'FEMALE';
    } else {
      return { valid: false, error: 'Invalid century or gender digit in CCCD.' };
    }

    const fullBirthYear = (century - 1) * 100 + birthYearSuffix;

    return {
      valid: true,
      details: {
        provinceCode,
        gender,
        century,
        birthYear: fullBirthYear,
      },
    };
  }

  /**
   * Validates Cambodian National ID card (Khmer NRIC):
   * Standard 9 numeric digits.
   */
  public static validateCambodianNric(nric: string): {
    valid: boolean;
    error?: string;
  } {
    if (!nric) return { valid: false, error: 'Khmer National ID is required.' };
    const clean = nric.trim();
    if (!/^\d{9}$/.test(clean)) {
      return {
        valid: false,
        error: 'Khmer National ID card must contain exactly 9 numeric digits.',
      };
    }
    return { valid: true };
  }

  /**
   * Evaluates OCR data quality and confidence against straight-through thresholds.
   */
  public static evaluateOcrQuality(data: OcrExtractedData): {
    isPassed: boolean;
    missingFields: string[];
    confidence: number;
    decision: 'ACCEPT' | 'USER_EDIT_REQUIRED' | 'RE_CAPTURE';
  } {
    const missingFields: string[] = [];
    if (!data.idNumber) missingFields.push('idNumber');
    if (!data.fullName) missingFields.push('fullName');
    if (!data.dateOfBirth) missingFields.push('dateOfBirth');

    const confidence = data.confidenceScore ?? 1.0;

    if (missingFields.length > 0 || confidence < 0.60) {
      return {
        isPassed: false,
        missingFields,
        confidence,
        decision: 'RE_CAPTURE',
      };
    }

    if (confidence < this.MIN_OCR_CONFIDENCE) {
      return {
        isPassed: true,
        missingFields,
        confidence,
        decision: 'USER_EDIT_REQUIRED',
      };
    }

    return {
      isPassed: true,
      missingFields: [],
      confidence,
      decision: 'ACCEPT',
    };
  }

  /**
   * Evaluates biometric facial liveness checks (Blink, Smile, Head Turn, 3D Depth).
   */
  public static evaluateLiveness(params: {
    livenessScore: number;
    faceMatchScore: number; // Comparison between selfie and ID card photo (0.0 - 1.0)
    failedActions?: string[];
  }): LivenessCheckResult {
    const { livenessScore, faceMatchScore, failedActions = [] } = params;

    const isLive = livenessScore >= this.MIN_LIVENESS_SCORE && faceMatchScore >= 0.70;
    let recommendation: 'APPROVE' | 'RETRY' | 'GO_TO_COUNTER' = 'APPROVE';

    if (!isLive) {
      if (livenessScore < 0.50 || faceMatchScore < 0.50) {
        recommendation = 'GO_TO_COUNTER';
      } else {
        recommendation = 'RETRY';
      }
    }

    const passedChecks: ('BLINK' | 'SMILE' | 'HEAD_TURN' | 'PASSIVE_3D')[] = [];
    if (livenessScore >= 0.75) passedChecks.push('PASSIVE_3D');
    if (!failedActions.includes('BLINK')) passedChecks.push('BLINK');
    if (!failedActions.includes('SMILE')) passedChecks.push('SMILE');
    if (!failedActions.includes('HEAD_TURN')) passedChecks.push('HEAD_TURN');

    return {
      isLive,
      livenessScore,
      passedChecks,
      failedChecks: failedActions,
      recommendation,
    };
  }
}

