import { appLogger } from '../logger/AppLogger';
import { AppEventBus, APP_EVENTS } from './AppEventBus';
import {
  getPushKey,
  registerPushKey,
  type PushPluginRequest,
} from 'react-native-bizmob-plugin';

export interface DeviceLoginAttemptPayload {
  attemptId: string;
  userId: string;
  deviceName?: string;
  deviceModel?: string;
  platform?: 'android' | 'ios' | 'web';
  location?: string;
  ipAddress?: string;
  timestamp: string;
}

export type DeviceLoginDecision = 'APPROVED' | 'REJECTED';

export type DeviceLoginAttemptListener = (attempt: DeviceLoginAttemptPayload) => void;

/**
 * Firebase Push & Remote Device Verification Service
 *
 * Handles push notification token registration with Firebase/FCM via native bizMOB bridge,
 * listens for silent/foreground push payloads regarding concurrent login attempts from other devices,
 * and broadcasts prompt requests to the UI.
 */
export class FirebasePushNotificationService {
  private static instance: FirebasePushNotificationService;
  private pushToken: string | null = null;
  private attemptListeners: Set<DeviceLoginAttemptListener> = new Set();
  private pendingAttempt: DeviceLoginAttemptPayload | null = null;

  public static getInstance(): FirebasePushNotificationService {
    if (!FirebasePushNotificationService.instance) {
      FirebasePushNotificationService.instance = new FirebasePushNotificationService();
    }
    return FirebasePushNotificationService.instance;
  }

  /**
   * Initializes Firebase Push Token retrieval and syncs with bizMOB / FCM backend.
   */
  public async initializePushToken(userId?: string): Promise<string | null> {
    try {
      appLogger.info('FirebasePushNotificationService', 'Retrieving Firebase Push Key...');
      const response = await getPushKey();
      if (response && response.result && response.body?.push_key) {
        this.pushToken = response.body.push_key;
        appLogger.info('FirebasePushNotificationService', 'Firebase Push Key retrieved successfully', {
          tokenPrefix: this.pushToken.slice(0, 10) + '...',
        });

        if (userId) {
          await this.registerTokenWithBackend(userId, this.pushToken);
        }
        return this.pushToken;
      }
      return null;
    } catch (error) {
      appLogger.error('FirebasePushNotificationService', 'Failed to initialize push key', error);
      return null;
    }
  }

  /**
   * Registers push token with enterprise push notification dispatch server.
   */
  public async registerTokenWithBackend(userId: string, token: string): Promise<boolean> {
    try {
      const payload: PushPluginRequest = {
        push_key: token,
      };
      const result = await registerPushKey(payload);
      appLogger.info('FirebasePushNotificationService', 'Registered push key with server', {
        userId,
        success: result.result,
      });
      return result.result;
    } catch (error) {
      appLogger.error('FirebasePushNotificationService', 'Error registering push key', error);
      return false;
    }
  }

  /**
   * Called when a push notification payload is received from Firebase Cloud Messaging (FCM).
   * E.g. { type: 'ANOTHER_DEVICE_LOGIN_ATTEMPT', attemptId: '123', deviceName: 'iPhone 15 Pro', ... }
   */
  public handleIncomingPushMessage(data: Record<string, any>): void {
    appLogger.info('FirebasePushNotificationService', 'Handling incoming FCM push message', data);

    if (data.type === 'ANOTHER_DEVICE_LOGIN_ATTEMPT' || data.action === 'DEVICE_VERIFY') {
      const attempt: DeviceLoginAttemptPayload = {
        attemptId: data.attemptId || String(Date.now()),
        userId: data.userId || 'current_user',
        deviceName: data.deviceName || data.deviceModel || 'Unknown Device',
        deviceModel: data.deviceModel,
        platform: data.platform || 'ios',
        location: data.location || 'Unknown Location',
        ipAddress: data.ipAddress,
        timestamp: data.timestamp || new Date().toLocaleTimeString(),
      };

      this.pendingAttempt = attempt;

      // Broadcast to listeners
      this.attemptListeners.forEach((listener) => {
        try {
          listener(attempt);
        } catch (err) {
          appLogger.error('FirebasePushNotificationService', 'Listener error', err);
        }
      });

      // Also publish via cross-remote AppEventBus
      AppEventBus.getInstance().publish('auth:another_device_login_attempt', attempt);
    }
  }

  /**
   * Responds to the backend with user decision: "It's me" (APPROVED) or "It's not me" (REJECTED).
   */
  public async submitDeviceLoginDecision(
    attemptId: string,
    decision: DeviceLoginDecision
  ): Promise<{ success: boolean; shouldLogoutCurrentDevice: boolean }> {
    appLogger.info('FirebasePushNotificationService', 'Submitting device login decision', {
      attemptId,
      decision,
    });

    try {
      if (this.pendingAttempt?.attemptId === attemptId) {
        this.pendingAttempt = null;
      }

      if (decision === 'APPROVED') {
        // "It's me": Each account can log in on one device only -> Current device should be logged out
        appLogger.info('FirebasePushNotificationService', 'Login approved for new device. Logging out current device...');
        AppEventBus.getInstance().publish(APP_EVENTS.AUTH_LOGGED_OUT, {
          reason: 'LOGGED_IN_FROM_ANOTHER_DEVICE',
        });
        return { success: true, shouldLogoutCurrentDevice: true };
      } else {
        // "It's not me": Block new attempt, secure credentials
        appLogger.warn('FirebasePushNotificationService', 'Unauthorized device login attempt blocked by user!');
        return { success: true, shouldLogoutCurrentDevice: false };
      }
    } catch (error) {
      appLogger.error('FirebasePushNotificationService', 'Failed to submit device decision', error);
      return { success: false, shouldLogoutCurrentDevice: false };
    }
  }

  /**
   * Subscribes to device login attempt alerts.
   */
  public onAnotherDeviceLoginAttempt(listener: DeviceLoginAttemptListener): () => void {
    this.attemptListeners.add(listener);
    if (this.pendingAttempt) {
      listener(this.pendingAttempt);
    }
    return () => {
      this.attemptListeners.delete(listener);
    };
  }

  public getPendingAttempt(): DeviceLoginAttemptPayload | null {
    return this.pendingAttempt;
  }

  public clearPendingAttempt(): void {
    this.pendingAttempt = null;
  }
}

export const firebasePushNotificationService = FirebasePushNotificationService.getInstance();
