export type LogLevel = 'DEBUG' | 'INFO' | 'WARN' | 'ERROR' | 'NONE';

export interface LogEntry {
  id: string;
  level: LogLevel;
  tag: string;
  message: string;
  timestamp: string;
  args?: any[];
  rawMessage: string;
}

export type LogListener = (entry: LogEntry) => void;

const LOG_LEVEL_PRIORITY: Record<LogLevel, number> = {
  DEBUG: 10,
  INFO: 20,
  WARN: 30,
  ERROR: 40,
  NONE: 100,
};

export interface LoggerConfig {
  /**
   * Master switch to enable or disable all console & network logging.
   * Can be toggled at runtime or driven by environment variables (`__DEV__`, `process.env.ENABLE_LOGGER`, etc.)
   */
  enabled: boolean;
  /**
   * Log level threshold. Messages below this severity will be silenced.
   * Default: 'DEBUG' in dev, 'WARN' or 'NONE' in production.
   */
  minLevel: LogLevel;
  /**
   * Optional tag prefix prepended to all output (e.g. `[LOS-APP]`).
   */
  prefix?: string;
  /**
   * Whether to include timestamps in log output.
   */
  timestamp?: boolean;
  /**
   * Maximum log buffer size preserved in memory for LogConsole. Default: 100
   */
  maxBufferSize?: number;
}

/**
 * Enterprise Configurable Logger (`AppLogger`)
 *
 * Allows managing log visibility globally via:
 * - Environment variable check: `process.env.ENABLE_LOGGER`, `process.env.LOG_LEVEL`, `__DEV__`
 * - Runtime property: `AppLogger.setEnabled(boolean)`, `AppLogger.setLevel('NONE' | 'DEBUG' | ...)`
 * - Partial config object: `AppLogger.configure({ enabled, minLevel, prefix })`
 */
const getEnvVar = (key: string): string | undefined => {
  if (typeof process !== 'undefined' && process.env) {
    return process.env[key];
  }
  return undefined;
};

export class AppLogger {
  private static instance: AppLogger;

  private config: LoggerConfig = {
    enabled: typeof __DEV__ !== 'undefined' ? __DEV__ : (getEnvVar('NODE_ENV') !== 'production'),
    minLevel: (getEnvVar('LOG_LEVEL') as LogLevel) || 'DEBUG',
    prefix: '[LOS]',
    timestamp: true,
    maxBufferSize: 100,
  };

  private logBuffer: LogEntry[] = [];
  private listeners: Set<LogListener> = new Set();
  private logCounter = 0;
  private isConsoleIntercepted = false;
  private originalConsole: {
    log?: typeof console.log;
    info?: typeof console.info;
    warn?: typeof console.warn;
    error?: typeof console.error;
    debug?: typeof console.debug;
  } = {};

  private constructor() {
    // Check custom environment flag override if present
    const enableLogger = getEnvVar('ENABLE_LOGGER');
    if (enableLogger !== undefined) {
      this.config.enabled = enableLogger === 'true' || enableLogger === '1';
    }
  }

  public static getInstance(): AppLogger {
    if (!AppLogger.instance) {
      AppLogger.instance = new AppLogger();
    }
    return AppLogger.instance;
  }

  /**
   * Reconfigure logger settings globally at runtime.
   */
  public configure(newConfig: Partial<LoggerConfig>): void {
    this.config = {
      ...this.config,
      ...newConfig,
    };
  }

  /**
   * Show or hide all logs.
   */
  public setEnabled(enabled: boolean): void {
    this.config.enabled = enabled;
  }

  /**
   * Returns whether logging is currently active.
   */
  public isEnabled(): boolean {
    return this.config.enabled && this.config.minLevel !== 'NONE';
  }

  /**
   * Set minimum log severity level.
   */
  public setMinLevel(level: LogLevel): void {
    this.config.minLevel = level;
  }

  public getMinLevel(): LogLevel {
    return this.config.minLevel;
  }

  private shouldLog(level: LogLevel): boolean {
    if (!this.config.enabled || this.config.minLevel === 'NONE') {
      return false;
    }
    const targetPri = LOG_LEVEL_PRIORITY[level] ?? 20;
    const minPri = LOG_LEVEL_PRIORITY[this.config.minLevel] ?? 20;
    return targetPri >= minPri;
  }

  private formatMessage(tag: string, message: string): string {
    const parts: string[] = [];
    if (this.config.prefix) {
      parts.push(this.config.prefix);
    }
    if (this.config.timestamp) {
      parts.push(`[${new Date().toLocaleTimeString()}]`);
    }
    if (tag) {
      parts.push(`[${tag}]`);
    }
    parts.push(message);
    return parts.join(' ');
  }

  private serializeLogArg(arg: any): any {
    if (arg === null || arg === undefined) return arg;
    if (arg instanceof Error) {
      return {
        name: arg.name,
        message: arg.message,
        ...(arg.stack ? { stack: arg.stack } : {}),
      };
    }
    // Handle objects with custom toJSON or plain error-like objects
    if (typeof arg === 'object' && ('message' in arg || 'stack' in arg)) {
      return {
        ...arg,
        message: arg.message,
        ...(arg.stack ? { stack: arg.stack } : {}),
      };
    }
    return arg;
  }

  private recordLog(level: LogLevel, tag: string, message: string, args: any[]): void {
    const max = this.config.maxBufferSize ?? 100;
    const now = new Date();
    const timestamp = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}:${now.getSeconds().toString().padStart(2, '0')}.${now.getMilliseconds().toString().padStart(3, '0')}`;
    this.logCounter += 1;
    const processedArgs = args.length > 0 ? args.map((a) => this.serializeLogArg(a)) : undefined;
    const entry: LogEntry = {
      id: `${Date.now()}-${this.logCounter}`,
      level,
      tag: tag || 'APP',
      message,
      timestamp,
      args: processedArgs,
      rawMessage: this.formatMessage(tag, message),
    };

    this.logBuffer.push(entry);
    if (this.logBuffer.length > max) {
      this.logBuffer.splice(0, this.logBuffer.length - max);
    }

    this.listeners.forEach((listener) => {
      try {
        listener(entry);
      } catch (err) {
        // Silently prevent crashing from listeners
      }
    });
  }

  /**
   * Subscribe to log events (for in-app LogConsole)
   * Returns an unsubscribe function.
   */
  public subscribe(listener: LogListener): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  /**
   * Get all captured logs currently stored in memory buffer.
   */
  public getLogs(): LogEntry[] {
    return [...this.logBuffer];
  }

  /**
   * Clear all captured logs from buffer and notify subscribers.
   */
  public clearLogs(): void {
    this.logBuffer = [];
  }

  /**
   * Automatically intercept standard `console.log`, `console.info`, `console.warn`, `console.error`
   * so third-party plugins (like bizMOB `logger.i`, `logger.e`, etc.) are captured seamlessly in `LogConsole`.
   */
  public interceptConsole(): void {
    if (this.isConsoleIntercepted || typeof console === 'undefined') {
      return;
    }

    this.originalConsole = {
      log: console.log.bind(console),
      info: console.info.bind(console),
      warn: console.warn.bind(console),
      error: console.error.bind(console),
      debug: (console.debug || console.log).bind(console),
    };

    const serializeArg = (arg: any): string => {
      if (arg === null) return 'null';
      if (arg === undefined) return 'undefined';
      if (typeof arg === 'string') return arg;
      if (arg instanceof Error) return `${arg.name}: ${arg.message}${arg.stack ? `\n${arg.stack}` : ''}`;
      try {
        return typeof arg === 'object' ? JSON.stringify(arg) : String(arg);
      } catch {
        return String(arg);
      }
    };

    const parseMessageAndTag = (args: any[]): { tag: string; message: string; extraArgs: any[] } => {
      if (args.length === 0) {
        return { tag: 'CONSOLE', message: '', extraArgs: [] };
      }

      const first = args[0];
      let messageStr = serializeArg(first);
      let tag = 'CONSOLE';
      const extraArgs = args.slice(1);

      // Check if message matches:
      // 1. "[LOS] [timestamp] [tag] message..."
      const losMatch = messageStr.match(/^\[LOS\]\s*(?:\[\d{1,2}:\d{2}:\d{2}.*?\]\s*)?\[(.*?)\]\s*(.*)$/);
      if (losMatch) {
        tag = losMatch[1];
        messageStr = losMatch[2];
      } else {
        // 2. "[timestamp] [tag] message..." (e.g. bizMOB)
        const timestampMatch = messageStr.match(/^\[(.*?)\]\s*\[(.*?)\]\s*(.*)$/);
        if (timestampMatch) {
          tag = timestampMatch[2];
          messageStr = timestampMatch[3];
        } else {
          // 3. "[tag] message..." (e.g. [webpack-dev-server] or [OTA])
          const tagMatch = messageStr.match(/^\[(.*?)\]\s*(.*)$/);
          if (tagMatch) {
            tag = tagMatch[1];
            messageStr = tagMatch[2];
          }
        }
      }

      return { tag, message: messageStr, extraArgs };
    };

    console.log = (...args: any[]) => {
      this.originalConsole.log?.(...args);
      const { tag, message, extraArgs } = parseMessageAndTag(args);
      this.recordLog('DEBUG', tag, message, extraArgs);
    };

    console.debug = (...args: any[]) => {
      this.originalConsole.debug?.(...args);
      const { tag, message, extraArgs } = parseMessageAndTag(args);
      this.recordLog('DEBUG', tag, message, extraArgs);
    };

    console.info = (...args: any[]) => {
      this.originalConsole.info?.(...args);
      const { tag, message, extraArgs } = parseMessageAndTag(args);
      this.recordLog('INFO', tag, message, extraArgs);
    };

    console.warn = (...args: any[]) => {
      this.originalConsole.warn?.(...args);
      const { tag, message, extraArgs } = parseMessageAndTag(args);
      this.recordLog('WARN', tag, message, extraArgs);
    };

    console.error = (...args: any[]) => {
      this.originalConsole.error?.(...args);
      const { tag, message, extraArgs } = parseMessageAndTag(args);
      // Ignore react test renderer act warnings from polluting the log buffer
      if (message.includes('not wrapped in act(...)')) {
        return;
      }
      this.recordLog('ERROR', tag, message, extraArgs);
    };

    // Listen to global unhandled browser window errors if running on web
    if (typeof window !== 'undefined' && typeof window.addEventListener === 'function') {
      window.addEventListener('error', (event: ErrorEvent) => {
        const errorMsg = event.message || (event.error ? event.error.message : 'Unknown Web Error');
        const filename = event.filename ? ` at ${event.filename}:${event.lineno}` : '';
        this.recordLog('ERROR', 'WebRuntime', `${errorMsg}${filename}`, event.error ? [event.error] : []);
      });

      window.addEventListener('unhandledrejection', (event: PromiseRejectionEvent) => {
        const reason = event.reason;
        const msg = reason instanceof Error ? reason.message : String(reason);
        this.recordLog('ERROR', 'UnhandledPromise', msg, reason ? [reason] : []);
      });
    }

    this.isConsoleIntercepted = true;
  }

  /**
   * Restore original console methods.
   */
  public restoreConsole(): void {
    if (!this.isConsoleIntercepted) {
      return;
    }
    if (this.originalConsole.log) console.log = this.originalConsole.log;
    if (this.originalConsole.info) console.info = this.originalConsole.info;
    if (this.originalConsole.warn) console.warn = this.originalConsole.warn;
    if (this.originalConsole.error) console.error = this.originalConsole.error;
    if (this.originalConsole.debug) console.debug = this.originalConsole.debug;
    this.isConsoleIntercepted = false;
  }

  public debug(tag: string, message: string, ...args: any[]): void {
    if (this.shouldLog('DEBUG')) {
      const output = this.isConsoleIntercepted && this.originalConsole.log ? this.originalConsole.log : console.log;
      output(this.formatMessage(tag, message), ...args);
    }
    this.recordLog('DEBUG', tag, message, args);
  }

  public info(tag: string, message: string, ...args: any[]): void {
    if (this.shouldLog('INFO')) {
      const output = this.isConsoleIntercepted && this.originalConsole.info ? this.originalConsole.info : console.info;
      output(this.formatMessage(tag, message), ...args);
    }
    this.recordLog('INFO', tag, message, args);
  }

  public warn(tag: string, message: string, ...args: any[]): void {
    if (this.shouldLog('WARN')) {
      const output = this.isConsoleIntercepted && this.originalConsole.warn ? this.originalConsole.warn : console.warn;
      output(this.formatMessage(tag, message), ...args);
    }
    this.recordLog('WARN', tag, message, args);
  }

  public error(tag: string, message: string, ...args: any[]): void {
    if (this.shouldLog('ERROR')) {
      const output = this.isConsoleIntercepted && this.originalConsole.error ? this.originalConsole.error : console.error;
      output(this.formatMessage(tag, message), ...args);
    }
    this.recordLog('ERROR', tag, message, args);
  }

  /**
   * Shorthand aliases
   */
  public d(tag: string, message: string, ...args: any[]): void {
    this.debug(tag, message, ...args);
  }

  public i(tag: string, message: string, ...args: any[]): void {
    this.info(tag, message, ...args);
  }

  public w(tag: string, message: string, ...args: any[]): void {
    this.warn(tag, message, ...args);
  }

  public e(tag: string, message: string, ...args: any[]): void {
    this.error(tag, message, ...args);
  }
}

export const appLogger = AppLogger.getInstance();
