export interface DraftRecord<T> {
  key: string;
  data: T;
  step?: string;
  /** Current step number, e.g. 5 */
  currentStep?: number;
  /** Total steps count, e.g. 12 */
  totalSteps?: number;
  /** Step label / title, e.g. "Additional information", "Select scheme" */
  stepTitle?: string;
  /** Customer / applicant name, e.g. "Hoàng Văn Tùng" */
  customerName?: string;
  /** Product or loan category name, e.g. "Cash Loan", "Durable Loan", "Car Loan" */
  productName?: string;
  /** Masked ID card / CCCD string, e.g. "079***4521" */
  idNumberMasked?: string;
  updatedAt: number;
}

export interface IDraftStorageAdapter {
  getItem(key: string): Promise<string | null>;
  setItem(key: string, value: string): Promise<void>;
  removeItem(key: string): Promise<void>;
}

const memoryStore = new Map<string, string>();

/**
 * Default storage adapter using in-memory Map (with web localStorage fallback if available).
 * Can be replaced with AsyncStorage or MMKV via `setDefaultAdapter` or per-call options.
 */
export const defaultDraftAdapter: IDraftStorageAdapter = {
  async getItem(key: string): Promise<string | null> {
    if (typeof globalThis !== 'undefined' && 'localStorage' in globalThis && globalThis.localStorage) {
      try {
        return globalThis.localStorage.getItem(key);
      } catch {
        // Fallback to memory store if localStorage is restricted
      }
    }
    return memoryStore.get(key) ?? null;
  },

  async setItem(key: string, value: string): Promise<void> {
    if (typeof globalThis !== 'undefined' && 'localStorage' in globalThis && globalThis.localStorage) {
      try {
        globalThis.localStorage.setItem(key, value);
        return;
      } catch {
        // Fallback to memory store
      }
    }
    memoryStore.set(key, value);
  },

  async removeItem(key: string): Promise<void> {
    if (typeof globalThis !== 'undefined' && 'localStorage' in globalThis && globalThis.localStorage) {
      try {
        globalThis.localStorage.removeItem(key);
        return;
      } catch {
        // Fallback to memory store
      }
    }
    memoryStore.delete(key);
  },
};

const DRAFT_PREFIX = '@mfe_draft:';

function buildStorageKey(key: string): string {
  return `${DRAFT_PREFIX}${key}`;
}

export class DraftStorageUtil {
  private static adapter: IDraftStorageAdapter = defaultDraftAdapter;

  static setDefaultAdapter(adapter: IDraftStorageAdapter): void {
    DraftStorageUtil.adapter = adapter;
  }

  static async saveDraft<T>(
    key: string,
    data: T,
    step?: string | {
      step?: string;
      currentStep?: number;
      totalSteps?: number;
      stepTitle?: string;
      customerName?: string;
      productName?: string;
      idNumberMasked?: string;
    },
    adapter: IDraftStorageAdapter = DraftStorageUtil.adapter
  ): Promise<DraftRecord<T>> {
    const meta = typeof step === 'object' && step !== null ? step : { step };
    const record: DraftRecord<T> = {
      key,
      data,
      step: meta.step,
      currentStep: meta.currentStep,
      totalSteps: meta.totalSteps,
      stepTitle: meta.stepTitle,
      customerName: meta.customerName,
      productName: meta.productName,
      idNumberMasked: meta.idNumberMasked,
      updatedAt: Date.now(),
    };
    await adapter.setItem(buildStorageKey(key), JSON.stringify(record));

    // Maintain global registry of draft keys for multi-application draft lists
    try {
      const indexRaw = await adapter.getItem('@mfe_draft_keys_index');
      const indexList: string[] = indexRaw ? JSON.parse(indexRaw) : [];
      if (!indexList.includes(key)) {
        indexList.push(key);
        await adapter.setItem('@mfe_draft_keys_index', JSON.stringify(indexList));
      }
    } catch {
      // index fallback
    }

    return record;
  }

  /**
   * Retrieves all active saved drafts in the storage index.
   */
  static async getAllDrafts<T = any>(
    adapter: IDraftStorageAdapter = DraftStorageUtil.adapter
  ): Promise<DraftRecord<T>[]> {
    try {
      const indexRaw = await adapter.getItem('@mfe_draft_keys_index');
      if (!indexRaw) return [];
      const keys: string[] = JSON.parse(indexRaw);
      const drafts: DraftRecord<T>[] = [];
      for (const k of keys) {
        const d = await DraftStorageUtil.getDraft<T>(k, adapter);
        if (d) {
          drafts.push(d);
        }
      }
      return drafts.sort((a, b) => b.updatedAt - a.updatedAt);
    } catch {
      return [];
    }
  }

  static async getDraft<T>(
    key: string,
    adapter: IDraftStorageAdapter = DraftStorageUtil.adapter
  ): Promise<DraftRecord<T> | null> {
    const raw = await adapter.getItem(buildStorageKey(key));
    if (!raw) {
      return null;
    }
    try {
      return JSON.parse(raw) as DraftRecord<T>;
    } catch {
      return null;
    }
  }

  static async hasDraft(
    key: string,
    adapter: IDraftStorageAdapter = DraftStorageUtil.adapter
  ): Promise<boolean> {
    const draft = await DraftStorageUtil.getDraft(key, adapter);
    return draft !== null;
  }

  static async clearDraft(
    key: string,
    adapter: IDraftStorageAdapter = DraftStorageUtil.adapter
  ): Promise<void> {
    await adapter.removeItem(buildStorageKey(key));

    // Remove from index
    try {
      const indexRaw = await adapter.getItem('@mfe_draft_keys_index');
      if (indexRaw) {
        const indexList: string[] = JSON.parse(indexRaw);
        const filtered = indexList.filter((k) => k !== key);
        await adapter.setItem('@mfe_draft_keys_index', JSON.stringify(filtered));
      }
    } catch {
      // index fallback
    }
  }

  /**
   * Creates a debounced auto-save controller for multi-step forms (e.g., loan application).
   */
  static createAutoSave<T>(
    key: string,
    options?: {
      debounceMs?: number;
      adapter?: IDraftStorageAdapter;
    }
  ) {
    const debounceMs = options?.debounceMs ?? 500;
    const adapter = options?.adapter ?? DraftStorageUtil.adapter;
    let timer: ReturnType<typeof setTimeout> | null = null;
    let pendingData: {
      data: T;
      step?: string | {
        step?: string;
        currentStep?: number;
        totalSteps?: number;
        stepTitle?: string;
        customerName?: string;
        productName?: string;
        idNumberMasked?: string;
      };
    } | null = null;

    const cancelPending = () => {
      if (timer !== null) {
        clearTimeout(timer);
        timer = null;
      }
      pendingData = null;
    };

    const flush = async (): Promise<DraftRecord<T> | null> => {
      if (!pendingData) {
        return null;
      }
      const { data, step } = pendingData;
      cancelPending();
      return DraftStorageUtil.saveDraft<T>(key, data, step, adapter);
    };

    const scheduleSave = (
      data: T,
      step?: string | {
        step?: string;
        currentStep?: number;
        totalSteps?: number;
        stepTitle?: string;
        customerName?: string;
        productName?: string;
        idNumberMasked?: string;
      }
    ): void => {
      if (timer !== null) {
        clearTimeout(timer);
      }
      pendingData = { data, step };
      timer = setTimeout(() => {
        flush().catch(() => {});
      }, debounceMs);
    };

    return {
      scheduleSave,
      flush,
      cancelPending,
      load: () => DraftStorageUtil.getDraft<T>(key, adapter),
      hasDraft: () => DraftStorageUtil.hasDraft(key, adapter),
      clear: async () => {
        cancelPending();
        await DraftStorageUtil.clearDraft(key, adapter);
      },
    };
  }
}

