import {
  callPhone as nativeCallPhone,
  sendSms as nativeSendSms,
  retrieveSmsOtp as nativeRetrieveSmsOtp,
  type TelRequest,
  type SmsRequest,
} from 'react-native-bizmob-plugin';
import { appLogger } from '../logger/AppLogger';

export interface TelephonyPluginAdapter {
  callPhone: typeof nativeCallPhone;
  sendSms: typeof nativeSendSms;
  retrieveSmsOtp: typeof nativeRetrieveSmsOtp;
}

const defaultAdapter: TelephonyPluginAdapter = {
  callPhone: nativeCallPhone,
  sendSms: nativeSendSms,
  retrieveSmsOtp: nativeRetrieveSmsOtp,
};

/**
 * Telephony & SMS Customer Contact Service (`TelephonyAndMessagingService`)
 *
 * Allows loan officers to call borrowers and send standardized payment reminder SMS
 * directly from customer profile and debtor collection lists.
 */
export class TelephonyAndMessagingService {
  private static instance: TelephonyAndMessagingService;
  private adapter: TelephonyPluginAdapter;

  constructor(adapter: TelephonyPluginAdapter = defaultAdapter) {
    this.adapter = adapter;
  }

  public static getInstance(): TelephonyPluginAdapter & any {
    if (!TelephonyAndMessagingService.instance) {
      TelephonyAndMessagingService.instance = new TelephonyAndMessagingService();
    }
    return TelephonyAndMessagingService.instance;
  }

  /**
   * Places a direct phone call or opens the system dialer with a customer's number.
   */
  public async makeCall(phoneNumber: string, directCall: boolean = false): Promise<boolean> {
    const cleanNumber = phoneNumber.replace(/[\s-]/g, '');
    appLogger.i('TelephonyAndMessagingService', `📞 Initiating call to: ${cleanNumber}`);

    try {
      const res = await this.adapter.callPhone({
        number: cleanNumber,
        direct_call: directCall,
      });
      return res?.header?.result ?? true;
    } catch (err) {
      appLogger.w('TelephonyAndMessagingService', '⚠️ Telephony call failed:', err);
      return false;
    }
  }

  /**
   * Opens the native SMS composer with recipient and prefilled message template.
   */
  public async sendSmsMessage(phoneNumber: string, message: string): Promise<boolean> {
    const cleanNumber = phoneNumber.replace(/[\s-]/g, '');
    try {
      const res = await this.adapter.sendSms({
        number: cleanNumber,
        message,
      });
      return res?.header?.result ?? true;
    } catch (err) {
      appLogger.w('TelephonyAndMessagingService', '⚠️ SMS dispatch failed:', err);
      return false;
    }
  }

  /**
   * Automatically listens for incoming SMS OTP for login verification without manual typing.
   */
  public async listenForSmsOtp(): Promise<string | null> {
    try {
      const res = await this.adapter.retrieveSmsOtp({ type: 'register' });
      if (res?.header?.result && res?.body?.otp) {
        return res.body.otp;
      }
    } catch {}
    return null;
  }
}

export const defaultTelephonyAndMessagingService = TelephonyAndMessagingService.getInstance();
