/**
 * Toast Utility and Event Bus for Global Notification Dispatch.
 * Enables zero-prop-drilling programmatic triggers from viewmodels, services,
 * network interceptors, and UI components across micro-frontends.
 */

export type ToastType = 'error' | 'success' | 'warning' | 'info';
export type ToastPosition = 'top' | 'bottom';

export interface ToastOptions {
  id?: string;
  type?: ToastType;
  message: string;
  duration?: number; // Milliseconds, default 3500. 0 for persistent until dismissed.
  position?: ToastPosition;
  showIcon?: boolean;
  showCloseButton?: boolean;
  onPress?: () => void;
  onDismiss?: () => void;
}

export type ToastListener = (toast: ToastOptions | null) => void;

class ToastEventEmitter {
  private listeners: Set<ToastListener> = new Set();
  private currentToast: ToastOptions | null = null;
  private timer: any = null;

  /**
   * Subscribe a ToastContainer listener (typically placed at root shell/app level).
   */
  public subscribe(listener: ToastListener): () => void {
    this.listeners.add(listener);
    if (this.currentToast) {
      listener(this.currentToast);
    }
    return () => {
      this.listeners.delete(listener);
    };
  }

  /**
   * Display a toast with full options.
   */
  public show(options: ToastOptions): string {
    const id = options.id || `toast-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`;
    const fullOptions: ToastOptions = {
      id,
      type: options.type || 'info',
      duration: options.duration !== undefined ? options.duration : 3500,
      position: options.position || 'top',
      showIcon: options.showIcon !== undefined ? options.showIcon : true,
      showCloseButton: options.showCloseButton !== undefined ? options.showCloseButton : true,
      ...options,
    };

    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }

    this.currentToast = fullOptions;
    this.emit(fullOptions);

    if (fullOptions.duration && fullOptions.duration > 0) {
      this.timer = setTimeout(() => {
        this.dismiss(id);
      }, fullOptions.duration);
    }

    return id;
  }

  /**
   * Shortcut for system error toast (matching Screenshot: "Hệ thống xảy ra lỗi, vui lòng thử lại.").
   */
  public error(message: string = 'Hệ thống xảy ra lỗi, vui lòng thử lại.', options?: Partial<ToastOptions>): string {
    return this.show({
      message,
      type: 'error',
      ...options,
    });
  }

  /**
   * Shortcut for success toast.
   */
  public success(message: string, options?: Partial<ToastOptions>): string {
    return this.show({
      message,
      type: 'success',
      ...options,
    });
  }

  /**
   * Shortcut for warning toast.
   */
  public warning(message: string, options?: Partial<ToastOptions>): string {
    return this.show({
      message,
      type: 'warning',
      ...options,
    });
  }

  /**
   * Shortcut for info toast.
   */
  public info(message: string, options?: Partial<ToastOptions>): string {
    return this.show({
      message,
      type: 'info',
      ...options,
    });
  }

  /**
   * Dismiss the currently active toast.
   */
  public dismiss(id?: string): void {
    if (!this.currentToast) return;
    if (id && this.currentToast.id !== id) return;

    if (this.timer) {
      clearTimeout(this.timer);
      this.timer = null;
    }

    const dismissed = this.currentToast;
    this.currentToast = null;
    this.emit(null);

    if (dismissed?.onDismiss) {
      dismissed.onDismiss();
    }
  }

  private emit(toast: ToastOptions | null) {
    this.listeners.forEach((listener) => {
      try {
        listener(toast);
      } catch (err) {
        console.warn('[ToastUtil] Listener error:', err);
      }
    });
  }
}

export const Toast = new ToastEventEmitter();
export const toastUtil = Toast;
