/**
 * DateTimeUtil: Comprehensive Date & Time Utility for Banking & LOS Workflows.
 * Designed for Loan Origination Systems, Core Banking Systems (CBS), eKYC, and Amortization Schedules.
 */

export interface DateParts {
  year: number;
  month: number; // 1 - 12
  day: number; // 1 - 31
  hours?: number;
  minutes?: number;
  seconds?: number;
}

export type ExpirationStatus = 'valid' | 'expiring_soon' | 'expired';

export interface ExpirationCheckResult {
  status: ExpirationStatus;
  isExpired: boolean;
  isExpiringSoon: boolean;
  daysRemaining: number;
  monthsRemaining: number;
  formattedExpirationDate: string;
  formattedDaysText: string;
}

export interface ExpirationOptions {
  warningDaysThreshold?: number; // e.g. 30, 60, or 90 days before expiration to flag 'expiring_soon'
  referenceDate?: Date | string | number; // Default: today
}

export class DateTimeUtil {
  /**
   * Formats a date into standard formats:
   * - 'DD/MM/YYYY' (Default VN/KH bank standard)
   * - 'YYYY-MM-DD' (ISO API request format)
   * - 'DD-MM-YYYY'
   * - 'YYYY/MM/DD'
   * - 'DD/MM/YYYY HH:mm:ss'
   * - 'DD Month YYYY'
   */
  public static formatDate(
    date: Date | string | number | null | undefined,
    format:
      | 'DD/MM/YYYY'
      | 'YYYY-MM-DD'
      | 'DD-MM-YYYY'
      | 'YYYY/MM/DD'
      | 'DD/MM/YYYY HH:mm'
      | 'DD/MM/YYYY HH:mm:ss'
      | 'YYYY-MM-DD HH:mm:ss'
      | 'DD MMM YYYY'
      | 'DD MMMM YYYY' = 'DD/MM/YYYY'
  ): string {
    if (!date) return '';

    const d = this.parseDate(date);
    if (!d || isNaN(d.getTime())) return '';

    const day = String(d.getDate()).padStart(2, '0');
    const month = String(d.getMonth() + 1).padStart(2, '0');
    const year = d.getFullYear();
    const hours = String(d.getHours()).padStart(2, '0');
    const minutes = String(d.getMinutes()).padStart(2, '0');
    const seconds = String(d.getSeconds()).padStart(2, '0');

    const monthNamesShort = [
      'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
      'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
    ];
    const monthNamesLong = [
      'January', 'February', 'March', 'April', 'May', 'June',
      'July', 'August', 'September', 'October', 'November', 'December',
    ];

    switch (format) {
      case 'DD/MM/YYYY':
        return `${day}/${month}/${year}`;
      case 'YYYY-MM-DD':
        return `${year}-${month}-${day}`;
      case 'DD-MM-YYYY':
        return `${day}-${month}-${year}`;
      case 'YYYY/MM/DD':
        return `${year}/${month}/${day}`;
      case 'DD/MM/YYYY HH:mm':
        return `${day}/${month}/${year} ${hours}:${minutes}`;
      case 'DD/MM/YYYY HH:mm:ss':
        return `${day}/${month}/${year} ${hours}:${minutes}:${seconds}`;
      case 'YYYY-MM-DD HH:mm:ss':
        return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
      case 'DD MMM YYYY':
        return `${day} ${monthNamesShort[d.getMonth()]} ${year}`;
      case 'DD MMMM YYYY':
        return `${day} ${monthNamesLong[d.getMonth()]} ${year}`;
      default:
        return `${day}/${month}/${year}`;
    }
  }

  /**
   * Safely parses arbitrary date inputs (Date, ISO string, timestamp, DD/MM/YYYY string).
   */
  public static parseDate(input: Date | string | number | null | undefined): Date | null {
    if (!input) return null;
    if (input instanceof Date) return isNaN(input.getTime()) ? null : input;
    if (typeof input === 'number') {
      const d = new Date(input);
      return isNaN(d.getTime()) ? null : d;
    }

    const str = String(input).trim();
    if (!str) return null;

    // Detect DD/MM/YYYY or DD-MM-YYYY format
    const ddmmyyyyMatch = str.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})(?:\s+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?$/);
    if (ddmmyyyyMatch) {
      const day = parseInt(ddmmyyyyMatch[1], 10);
      const month = parseInt(ddmmyyyyMatch[2], 10) - 1;
      const year = parseInt(ddmmyyyyMatch[3], 10);
      const hours = ddmmyyyyMatch[4] ? parseInt(ddmmyyyyMatch[4], 10) : 0;
      const minutes = ddmmyyyyMatch[5] ? parseInt(ddmmyyyyMatch[5], 10) : 0;
      const seconds = ddmmyyyyMatch[6] ? parseInt(ddmmyyyyMatch[6], 10) : 0;
      const parsed = new Date(year, month, day, hours, minutes, seconds);
      return isNaN(parsed.getTime()) ? null : parsed;
    }

    const parsed = new Date(str);
    return isNaN(parsed.getTime()) ? null : parsed;
  }

  /**
   * Calculates age in completed years from Date of Birth (DOB).
   * Commonly required in underwriting rule: borrower age must be between 18 and 60/65.
   */
  public static calculateAge(
    dob: Date | string | number,
    referenceDate: Date = new Date()
  ): number {
    const birthDate = this.parseDate(dob);
    if (!birthDate) return 0;

    let age = referenceDate.getFullYear() - birthDate.getFullYear();
    const monthDiff = referenceDate.getMonth() - birthDate.getMonth();
    if (monthDiff < 0 || (monthDiff === 0 && referenceDate.getDate() < birthDate.getDate())) {
      age--;
    }
    return Math.max(0, age);
  }

  /**
   * Validates whether a customer satisfies the age criteria (e.g. min 18, max 60).
   */
  public static isValidBorrowerAge(
    dob: Date | string | number,
    minAge: number = 18,
    maxAge: number = 60,
    referenceDate: Date = new Date()
  ): { valid: boolean; age: number; reason?: string } {
    const age = this.calculateAge(dob, referenceDate);
    if (age < minAge) {
      return {
        valid: false,
        age,
        reason: `Borrower must be at least ${minAge} years old (current: ${age}).`,
      };
    }
    if (age > maxAge) {
      return {
        valid: false,
        age,
        reason: `Borrower exceeds maximum eligible age of ${maxAge} years (current: ${age}).`,
      };
    }
    return { valid: true, age };
  }

  /**
   * Adds specified number of months to a date.
   * Handles month-end rollovers correctly (e.g. Jan 31 + 1 month -> Feb 28/29).
   */
  public static addMonths(date: Date | string | number, months: number): Date {
    const d = this.parseDate(date) || new Date();
    const targetMonth = d.getMonth() + months;
    const targetDate = new Date(d.getFullYear(), targetMonth, 1);
    
    // Find the last day of target month
    const lastDayOfTargetMonth = new Date(
      targetDate.getFullYear(),
      targetDate.getMonth() + 1,
      0
    ).getDate();

    const newDay = Math.min(d.getDate(), lastDayOfTargetMonth);
    return new Date(
      targetDate.getFullYear(),
      targetDate.getMonth(),
      newDay,
      d.getHours(),
      d.getMinutes(),
      d.getSeconds()
    );
  }

  /**
   * Adds specified number of days to a date.
   */
  public static addDays(date: Date | string | number, days: number): Date {
    const d = this.parseDate(date) || new Date();
    const result = new Date(d.getTime());
    result.setDate(result.getDate() + days);
    return result;
  }

  /**
   * Calculates the difference in days between two dates (date2 - date1).
   */
  public static diffInDays(
    date1: Date | string | number,
    date2: Date | string | number
  ): number {
    const d1 = this.parseDate(date1);
    const d2 = this.parseDate(date2);
    if (!d1 || !d2) return 0;

    const msPerDay = 1000 * 60 * 60 * 24;
    const utc1 = Date.UTC(d1.getFullYear(), d1.getMonth(), d1.getDate());
    const utc2 = Date.UTC(d2.getFullYear(), d2.getMonth(), d2.getDate());
    return Math.floor((utc2 - utc1) / msPerDay);
  }

  /**
   * Checks if a date falls on a weekend (Saturday or Sunday).
   */
  public static isWeekend(date: Date | string | number): boolean {
    const d = this.parseDate(date);
    if (!d) return false;
    const day = d.getDay();
    return day === 0 || day === 6;
  }

  /**
   * Adjusts a repayment date to the nearest preceding or following business day
   * based on banking holiday / weekend policy.
   * Default convention: 'following' (next Monday if Sunday).
   */
  public static adjustToBusinessDay(
    date: Date | string | number,
    convention: 'following' | 'preceding' = 'following',
    holidays: string[] = []
  ): Date {
    let d = this.parseDate(date) || new Date();
    const holidaySet = new Set(holidays);

    const isNonWorkingDay = (checkDate: Date): boolean => {
      const formatted = this.formatDate(checkDate, 'YYYY-MM-DD');
      return this.isWeekend(checkDate) || holidaySet.has(formatted);
    };

    while (isNonWorkingDay(d)) {
      d = convention === 'following' ? this.addDays(d, 1) : this.addDays(d, -1);
    }
    return d;
  }

  /**
   * Computes the recurring monthly repayment due date from a base disbursement date.
   * e.g., Disbursed 15/09/2026, installment 1 due on 15/10/2026.
   * Clamps day to month maximum if target month has fewer days.
   */
  public static calculateDueDate(
    disbursementDate: Date | string | number,
    installmentIndex: number, // 1-based (1 = first month)
    fixedRepaymentDay?: number
  ): Date {
    const base = this.parseDate(disbursementDate) || new Date();
    const targetMonthDate = this.addMonths(base, installmentIndex);

    if (fixedRepaymentDay && fixedRepaymentDay >= 1 && fixedRepaymentDay <= 31) {
      const maxDayInMonth = new Date(
        targetMonthDate.getFullYear(),
        targetMonthDate.getMonth() + 1,
        0
      ).getDate();
      const clampedDay = Math.min(fixedRepaymentDay, maxDayInMonth);
      return new Date(
        targetMonthDate.getFullYear(),
        targetMonthDate.getMonth(),
        clampedDay,
        base.getHours(),
        base.getMinutes()
      );
    }

    return targetMonthDate;
  }

  /**
   * Returns a user-friendly relative time string (e.g. "Just now", "5 mins ago", "Yesterday").
   */
  public static getRelativeTime(date: Date | string | number, now: Date = new Date()): string {
    const d = this.parseDate(date);
    if (!d) return '';

    const diffSeconds = Math.floor((now.getTime() - d.getTime()) / 1000);
    if (diffSeconds < 0) return this.formatDate(d, 'DD/MM/YYYY');
    if (diffSeconds < 60) return 'Just now';

    const diffMinutes = Math.floor(diffSeconds / 60);
    if (diffMinutes < 60) return `${diffMinutes}m ago`;

    const diffHours = Math.floor(diffMinutes / 60);
    if (diffHours < 24) return `${diffHours}h ago`;

    const diffDays = Math.floor(diffHours / 24);
    if (diffDays === 1) return 'Yesterday';
    if (diffDays < 7) return `${diffDays}d ago`;

    return this.formatDate(d, 'DD/MM/YYYY');
  }

  // =========================================================================
  // EXPIRATION DATE UTILITIES (ID Cards, Passports, Documents, Loans, OTPs)
  // =========================================================================

  /**
   * Evaluates the expiration status of a date against today or a reference date.
   * Commonly used for:
   * - Citizen ID cards (CCCD/CMND expiration dates)
   * - Passports, driver licenses, labor contracts
   * - Credit card validity (MM/YY)
   * - Loan approval term sheets and disbursement deadlines
   * - Temporary session tokens, OTPs, or draft applications
   *
   * @param expirationDate The target expiration date
   * @param options Thresholds and custom reference date
   */
  public static checkExpiration(
    expirationDate: Date | string | number | null | undefined,
    options?: ExpirationOptions
  ): ExpirationCheckResult {
    const warningDays = options?.warningDaysThreshold !== undefined ? options.warningDaysThreshold : 30;
    const refDate = options?.referenceDate ? this.parseDate(options.referenceDate) || new Date() : new Date();

    const expDate = this.parseDate(expirationDate);
    if (!expDate) {
      return {
        status: 'expired',
        isExpired: true,
        isExpiringSoon: false,
        daysRemaining: -999999,
        monthsRemaining: -9999,
        formattedExpirationDate: '',
        formattedDaysText: 'Invalid or missing date',
      };
    }

    // Set comparison to midnight for strict calendar day comparison
    const startOfRef = new Date(refDate.getFullYear(), refDate.getMonth(), refDate.getDate());
    const startOfExp = new Date(expDate.getFullYear(), expDate.getMonth(), expDate.getDate());

    const diffMs = startOfExp.getTime() - startOfRef.getTime();
    const daysRemaining = Math.round(diffMs / (1000 * 60 * 60 * 24));
    const monthsRemaining = Number((daysRemaining / 30.4375).toFixed(1));

    const isExpired = daysRemaining < 0;
    const isExpiringSoon = daysRemaining >= 0 && daysRemaining <= warningDays;

    let status: ExpirationStatus = 'valid';
    if (isExpired) {
      status = 'expired';
    } else if (isExpiringSoon) {
      status = 'expiring_soon';
    }

    let formattedDaysText = '';
    if (daysRemaining < 0) {
      const daysOver = Math.abs(daysRemaining);
      formattedDaysText = `Đã hết hạn ${daysOver} ngày trước`;
    } else if (daysRemaining === 0) {
      formattedDaysText = 'Hết hạn hôm nay';
    } else if (daysRemaining === 1) {
      formattedDaysText = 'Còn 1 ngày nữa sẽ hết hạn';
    } else if (daysRemaining <= warningDays) {
      formattedDaysText = `Còn ${daysRemaining} ngày nữa sẽ hết hạn`;
    } else {
      formattedDaysText = `Còn ${daysRemaining} ngày`;
    }

    return {
      status,
      isExpired,
      isExpiringSoon,
      daysRemaining,
      monthsRemaining,
      formattedExpirationDate: this.formatDate(expDate, 'DD/MM/YYYY'),
      formattedDaysText,
    };
  }

  /**
   * Fast boolean check if a date is expired.
   */
  public static isExpired(
    expirationDate: Date | string | number | null | undefined,
    referenceDate?: Date | string | number
  ): boolean {
    return this.checkExpiration(expirationDate, { referenceDate }).isExpired;
  }

  /**
   * Fast boolean check if a date is expiring soon within `warningDays`.
   */
  public static isExpiringSoon(
    expirationDate: Date | string | number | null | undefined,
    warningDays: number = 30,
    referenceDate?: Date | string | number
  ): boolean {
    return this.checkExpiration(expirationDate, {
      warningDaysThreshold: warningDays,
      referenceDate,
    }).isExpiringSoon;
  }

  /**
   * Computes the statutory Vietnamese CCCD expiration date based on birth date according to Citizen Identity Law.
   * Under VN Law:
   * - Citizen cards must be renewed at ages 25, 40, and 60.
   * - If a card is issued within 2 years before reaching the age milestone, it remains valid until the next milestone.
   * - Citizens aged 60 and above receive a card with lifetime validity (no expiration).
   *
   * @param dateOfBirth Citizen birth date
   * @returns Expiration Date, or null if lifetime valid
   */
  public static calculateCccdExpirationDate(
    dateOfBirth: Date | string | number
  ): Date | null {
    const dob = this.parseDate(dateOfBirth);
    if (!dob) return null;

    const currentAge = this.calculateAge(dob);

    // After age 60: Permanent / Lifetime validity
    if (currentAge >= 60) {
      return null;
    }

    let milestoneAge = 25;
    if (currentAge >= 40) {
      milestoneAge = 60;
    } else if (currentAge >= 25) {
      milestoneAge = 40;
    }

    return new Date(dob.getFullYear() + milestoneAge, dob.getMonth(), dob.getDate());
  }

  /**
   * Parses credit card expiration string format 'MM/YY' or 'MM/YYYY' into a Date
   * set to the end of that month (23:59:59.999).
   * e.g., '12/26' -> end of December 2026.
   */
  public static parseCardExpirationDate(monthYearStr: string): Date | null {
    if (!monthYearStr) return null;
    const clean = monthYearStr.trim().replace(/\s+/g, '');
    const match = clean.match(/^(\d{1,2})[/-](\d{2}|\d{4})$/);
    if (!match) return null;

    const month = parseInt(match[1], 10);
    let year = parseInt(match[2], 10);
    if (year < 100) {
      year += 2000;
    }

    if (month < 1 || month > 12) return null;

    // Last day of that month
    return new Date(year, month, 0, 23, 59, 59, 999);
  }

  /**
   * Checks if a credit card 'MM/YY' string is expired.
   */
  public static isCardExpired(monthYearStr: string, referenceDate?: Date | string | number): boolean {
    const expDate = this.parseCardExpirationDate(monthYearStr);
    if (!expDate) return true;
    const ref = referenceDate ? this.parseDate(referenceDate) || new Date() : new Date();
    return expDate.getTime() < ref.getTime();
  }

  /**
   * Formats a duration in seconds into MM:SS countdown format (useful for OTPs, eKYC timers).
   */
  public static formatCountdown(remainingSeconds: number): string {
    if (remainingSeconds <= 0) return '00:00';
    const mins = Math.floor(remainingSeconds / 60);
    const secs = Math.floor(remainingSeconds % 60);
    return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
  }
}

