import {
  checkRoot as nativeCheckRoot,
  type RootCheckResponse,
} from 'react-native-bizmob-plugin';
import { appLogger } from '../logger/AppLogger';

export interface DeviceSecurityStatus {
  isRootedOrJailbroken: boolean;
  isEmulator: boolean;
  isDebuggerAttached: boolean;
  isSecure: boolean;
  details?: Record<string, any>;
}

export interface SecurityPluginAdapter {
  checkRoot: typeof nativeCheckRoot;
}

const defaultAdapter: SecurityPluginAdapter = {
  checkRoot: nativeCheckRoot,
};

/**
 * Device Security & Integrity Inspection Service (`AppSecurityInspectionService`)
 *
 * Verifies that the app is executing inside a secure runtime environment:
 * - Detects Android root binaries (`/system/bin/su`, Magisk) & iOS jailbreak (Cydia).
 * - Identifies emulators and active debuggers.
 */
export class AppSecurityInspectionService {
  private static instance: AppSecurityInspectionService;
  private adapter: SecurityPluginAdapter;

  constructor(adapter: SecurityPluginAdapter = defaultAdapter) {
    this.adapter = adapter;
  }

  public static getInstance(): AppSecurityInspectionService {
    if (!AppSecurityInspectionService.instance) {
      AppSecurityInspectionService.instance = new AppSecurityInspectionService();
    }
    return AppSecurityInspectionService.instance;
  }

  /**
   * Performs an environment audit to verify device integrity.
   */
  public async inspectDeviceIntegrity(): Promise<DeviceSecurityStatus> {
    let isRooted = false;
    let isEmulator = false;
    let isDebuggerAttached = false;
    let details: Record<string, any> = {};

    try {
      const rootRes: RootCheckResponse = await this.adapter.checkRoot();
      if (rootRes && rootRes.body) {
        isRooted = rootRes.body.isRooted === true || rootRes.body.result === true;
        isEmulator = rootRes.body.isEmulator === true;
        isDebuggerAttached = rootRes.body.isDebuggerAttached === true;
        details = rootRes.body;
      }
    } catch (err) {
      appLogger.w('AppSecurityInspectionService', '⚠️ Root check plugin error:', err);
    }

    const isSecure = !isRooted && !isDebuggerAttached;

    if (!isSecure) {
      appLogger.w('AppSecurityInspectionService', '🚨 DEVICE INTEGRITY WARNING: Potential compromise detected!', {
        isRooted,
        isEmulator,
        isDebuggerAttached,
      });
    }

    return {
      isRootedOrJailbroken: isRooted,
      isEmulator,
      isDebuggerAttached,
      isSecure,
      details,
    };
  }
}

export const defaultAppSecurityInspectionService = AppSecurityInspectionService.getInstance();
