/**
 * Debt Service Ratio (DSR) & Debt Service Coverage Ratio (DSCR) Calculator
 *
 * Implements standard retail and SME underwriting decision criteria:
 * - DSR = (Total Monthly Debt Obligations / Net Monthly Income) * 100
 * - DSCR = Net Operating Income / Total Debt Service
 */

export interface DsrInput {
  netMonthlyIncome: number;
  existingDebtObligations: number;
  newLoanMonthlyInstallment: number;
}

export type DsrRiskLevel = 'ACCEPTABLE' | 'CAUTION' | 'HIGH_RISK';

export interface DsrResult {
  dsrPercent: number;
  totalMonthlyObligations: number;
  riskLevel: DsrRiskLevel;
  maxAllowableInstallment: number;
  isEligible: boolean;
}

/**
 * Calculates Debt Service Ratio (DSR) for consumer and micro-business loans.
 * Benchmark: DSR <= 50% (Acceptable), 50-70% (Caution), > 70% (High Risk)
 */
export function calculateDsr(input: DsrInput, maxDsrThreshold: number = 60): DsrResult {
  const { netMonthlyIncome, existingDebtObligations, newLoanMonthlyInstallment } = input;

  if (netMonthlyIncome <= 0) {
    return {
      dsrPercent: 100,
      totalMonthlyObligations: existingDebtObligations + newLoanMonthlyInstallment,
      riskLevel: 'HIGH_RISK',
      maxAllowableInstallment: 0,
      isEligible: false,
    };
  }

  const totalObligations = existingDebtObligations + newLoanMonthlyInstallment;
  const dsrPercent = Math.round((totalObligations / netMonthlyIncome) * 1000) / 10;

  let riskLevel: DsrRiskLevel = 'ACCEPTABLE';
  if (dsrPercent > 70) {
    riskLevel = 'HIGH_RISK';
  } else if (dsrPercent > 50) {
    riskLevel = 'CAUTION';
  }

  const maxTotalAllowed = (netMonthlyIncome * maxDsrThreshold) / 100;
  const maxAllowableInstallment = Math.max(0, Math.round(maxTotalAllowed - existingDebtObligations));

  return {
    dsrPercent,
    totalMonthlyObligations: totalObligations,
    riskLevel,
    maxAllowableInstallment,
    isEligible: dsrPercent <= maxDsrThreshold,
  };
}

/**
 * Calculates Debt Service Coverage Ratio (DSCR) for commercial/SME underwriting.
 * Formula: DSCR = Net Operating Income / Annual Debt Service
 * Benchmark: >= 1.25 is typical banking requirement.
 */
export function calculateDscr(netOperatingIncome: number, annualDebtService: number): {
  dscr: number;
  isAcceptable: boolean;
} {
  if (annualDebtService <= 0) {
    return { dscr: 999, isAcceptable: true };
  }
  const dscr = Math.round((netOperatingIncome / annualDebtService) * 100) / 100;
  return {
    dscr,
    isAcceptable: dscr >= 1.25,
  };
}
