/**
 * LoadingUtil: Enterprise Programmatic Loading & Spinner Utility.
 * Allows ViewModels, network interceptors, authentication guards,
 * and long-running services to trigger full-screen or card loading overlays
 * without prop drilling.
 */

export interface LoadingOptions {
  /** Optional message displayed below the spinner (e.g. "Đang xử lý hồ sơ...") */
  message?: string;
  /** Secondary subtitle (e.g. "Vui lòng không thoát ứng dụng") */
  subMessage?: string;
  /** Primary indicator color, defaults to Lotte Red #E5252A or Primary Blue */
  color?: string;
  /** Size of indicator: 'small' | 'large', defaults to 'large' */
  size?: 'small' | 'large' | number;
  /** Whether tapping the backdrop can cancel the loading, defaults to false */
  cancelable?: boolean;
  /** Callback triggered if canceled */
  onCancel?: () => void;
  /** Visual variant: 'modal' (full-screen modal with card) | 'overlay' (dimmed backdrop) | 'transparent' */
  variant?: 'modal' | 'overlay' | 'transparent';
  /** Accessible testID */
  testID?: string;
}

export interface LoadingState {
  visible: boolean;
  options: LoadingOptions;
}

export type LoadingListener = (state: LoadingState) => void;

class LoadingController {
  private listeners: Set<LoadingListener> = new Set();
  private state: LoadingState = {
    visible: false,
    options: {},
  };
  private autoDismissTimer: any = null;

  /**
   * Subscribe to loading state changes (used by GlobalLoadingOverlay).
   */
  public subscribe(listener: LoadingListener): () => void {
    this.listeners.add(listener);
    listener(this.state);
    return () => {
      this.listeners.delete(listener);
    };
  }

  /**
   * Show global loading spinner with optional message and configuration.
   *
   * @param messageOrOptions Message string or full LoadingOptions object
   * @param timeoutMs Optional auto-dismiss safety timeout in milliseconds
   */
  public show(messageOrOptions?: string | LoadingOptions, timeoutMs?: number): void {
    if (this.autoDismissTimer) {
      clearTimeout(this.autoDismissTimer);
      this.autoDismissTimer = null;
    }

    let options: LoadingOptions = {};
    if (typeof messageOrOptions === 'string') {
      options = { message: messageOrOptions };
    } else if (messageOrOptions) {
      options = messageOrOptions;
    }

    this.state = {
      visible: true,
      options: {
        color: '#E5252A',
        size: 'large',
        variant: 'modal',
        ...options,
      },
    };

    this.notify();

    if (timeoutMs && timeoutMs > 0) {
      this.autoDismissTimer = setTimeout(() => {
        this.hide();
      }, timeoutMs);
    }
  }

  /**
   * Hide global loading spinner.
   */
  public hide(): void {
    if (this.autoDismissTimer) {
      clearTimeout(this.autoDismissTimer);
      this.autoDismissTimer = null;
    }

    if (!this.state.visible) return;

    this.state = {
      visible: false,
      options: {},
    };
    this.notify();
  }

  /**
   * Wrap an async task with automatic loading show and hide.
   *
   * @param task Async function to execute
   * @param messageOrOptions Loading message or options during execution
   * @returns Result of the task
   */
  public async wrap<T>(
    task: () => Promise<T>,
    messageOrOptions?: string | LoadingOptions
  ): Promise<T> {
    this.show(messageOrOptions);
    try {
      return await task();
    } finally {
      this.hide();
    }
  }

  /**
   * Returns current active loading state (for tests and inspection).
   */
  public getState(): LoadingState {
    return this.state;
  }

  private notify(): void {
    this.listeners.forEach((listener) => {
      try {
        listener(this.state);
      } catch (err) {
        console.warn('[LoadingUtil] Listener error:', err);
      }
    });
  }
}

export const LoadingUtil = new LoadingController();
export const loadingUtil = LoadingUtil;
