import { createNavigationContainerRef } from '@react-navigation/native';
import { RootStackParamList } from '../../../navigation/NavigationTypes';

/**
 * Global Navigation Container Reference
 * Allows imperative navigation from services, push notification handlers,
 * background tasks, and native bridge callbacks without needing React hooks.
 */
export const navigationRef = createNavigationContainerRef<RootStackParamList>();

export class NavigationService {
  /**
   * Navigate to any root or nested screen
   */
  public static navigate<RouteName extends keyof RootStackParamList>(
    name: RouteName,
    params?: RootStackParamList[RouteName]
  ): boolean {
    if (navigationRef.isReady()) {
      (navigationRef as any).navigate(name, params);
      return true;
    }
    return false;
  }

  /**
   * Reset navigation stack to a specific screen
   */
  public static reset(name: keyof RootStackParamList, params?: any): boolean {
    if (navigationRef.isReady()) {
      navigationRef.reset({
        index: 0,
        routes: [{ name: name as any, params }],
      });
      return true;
    }
    return false;
  }

  /**
   * Go back in navigation stack
   */
  public static goBack(): boolean {
    if (navigationRef.isReady() && navigationRef.canGoBack()) {
      navigationRef.goBack();
      return true;
    }
    return false;
  }

  /**
   * Get current active route name
   */
  public static getCurrentRouteName(): string | undefined {
    if (navigationRef.isReady()) {
      return navigationRef.getCurrentRoute()?.name;
    }
    return undefined;
  }
}
