import { DraftStorage } from './draftStorage';

export type DraftActionChoice = 'continue' | 'save_draft' | 'leave';

export interface UnsavedChangesPromptOptions<T = any> {
  draftKey: string;
  data: T;
  title?: string;
  message?: string;
  continueLabel?: string;
  saveDraftLabel?: string;
  leaveLabel?: string;
  onSaved?: () => void;
  onLeave?: () => void;
  onContinue?: () => void;
}

export type PromptListener = (
  options: UnsavedChangesPromptOptions | null,
  resolver?: (choice: DraftActionChoice) => void
) => void;

class DraftPromptController {
  private listeners: Set<PromptListener> = new Set();
  private activePrompt: UnsavedChangesPromptOptions | null = null;
  private activeResolver: ((choice: DraftActionChoice) => void) | null = null;

  public subscribe(listener: PromptListener): () => void {
    this.listeners.add(listener);
    if (this.activePrompt && this.activeResolver) {
      listener(this.activePrompt, this.activeResolver);
    }
    return () => {
      this.listeners.delete(listener);
    };
  }

  /**
   * Prompts the user with the 3 options:
   * 1. 'continue': Stay on screen and continue editing
   * 2. 'save_draft': Automatically saves form data to DraftStorage and proceeds to leave
   * 3. 'leave': Leaves screen immediately discarding changes
   *
   * @returns Promise resolving to 'continue' | 'save_draft' | 'leave'
   */
  public prompt<T = any>(options: UnsavedChangesPromptOptions<T>): Promise<DraftActionChoice> {
    return new Promise((resolve) => {
      this.activePrompt = options;
      this.activeResolver = async (choice: DraftActionChoice) => {
        this.activePrompt = null;
        this.activeResolver = null;
        this.emit(null);

        if (choice === 'save_draft') {
          await DraftStorage.saveDraft(options.draftKey, options.data);
          if (options.onSaved) {
            options.onSaved();
          }
        } else if (choice === 'leave') {
          if (options.onLeave) {
            options.onLeave();
          }
        } else if (choice === 'continue') {
          if (options.onContinue) {
            options.onContinue();
          }
        }

        resolve(choice);
      };

      this.emit(this.activePrompt, this.activeResolver);
    });
  }

  /**
   * Dismiss prompt without action (defaults to 'continue').
   */
  public dismiss(): void {
    if (this.activeResolver) {
      this.activeResolver('continue');
    }
  }

  public getActivePrompt(): UnsavedChangesPromptOptions | null {
    return this.activePrompt;
  }

  private emit(
    prompt: UnsavedChangesPromptOptions | null,
    resolver?: (choice: DraftActionChoice) => void
  ) {
    this.listeners.forEach((listener) => {
      try {
        listener(prompt, resolver);
      } catch (err) {
        console.warn('[DraftPromptUtil] Listener error:', err);
      }
    });
  }
}

export const DraftPromptUtil = new DraftPromptController();
export const draftPromptUtil = DraftPromptUtil;
