export interface IdCardValidationResult {
  isValid: boolean;
  type?: 'OLD_9_DIGIT' | 'NEW_12_DIGIT' | 'PASSPORT' | 'UNKNOWN';
  error?: string;
}

export class IdCardValidator {
  /**
   * Validates National ID card (9 or 12 digits) or Passport format.
   */
  public static validateIdCard(idNumber: string): IdCardValidationResult {
    if (!idNumber) {
      return { isValid: false, error: 'ID number is required' };
    }

    const clean = idNumber.trim().toUpperCase();

    // 9-digit old format
    if (/^\d{9}$/.test(clean)) {
      return { isValid: true, type: 'OLD_9_DIGIT' };
    }

    // 12-digit standard chip card
    if (/^\d{12}$/.test(clean)) {
      return { isValid: true, type: 'NEW_12_DIGIT' };
    }

    // Passport (Letter + 7-8 digits)
    if (/^[A-Z][0-9]{7,8}$/.test(clean)) {
      return { isValid: true, type: 'PASSPORT' };
    }

    return {
      isValid: false,
      type: 'UNKNOWN',
      error: 'ID card format is invalid (must be 9 digits, 12 digits, or passport)',
    };
  }

  /**
   * Validates customer age based on Date of Birth string (YYYY-MM-DD or DD/MM/YYYY).
   * Eligible loan age range: minAge (default 18) to maxAge (default 65).
   */
  public static validateBorrowerAge(
    dobString: string,
    minAge: number = 18,
    maxAge: number = 65
  ): { isEligible: boolean; age: number; error?: string } {
    let birthDate: Date;

    if (dobString.includes('/')) {
      const [d, m, y] = dobString.split('/').map(Number);
      birthDate = new Date(y, m - 1, d);
    } else {
      birthDate = new Date(dobString);
    }

    if (isNaN(birthDate.getTime())) {
      return { isEligible: false, age: 0, error: 'Invalid date of birth format' };
    }

    const today = new Date();
    let age = today.getFullYear() - birthDate.getFullYear();
    const m = today.getMonth() - birthDate.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
      age--;
    }

    if (age < minAge) {
      return { isEligible: false, age, error: `Borrower must be at least ${minAge} years old` };
    }

    if (age > maxAge) {
      return { isEligible: false, age, error: `Borrower exceeds maximum eligible age of ${maxAge}` };
    }

    return { isEligible: true, age };
  }
}

