/**
 * Image & Camera Photo Pre-Processing Utilities
 *
 * Provides dimensions inspection, payload size estimation, and compression targets
 * for customer eKYC documents, collateral deeds, and site inspection photos
 * to prevent upload timeouts over mobile 3G/4G networks.
 */

export interface ImageDimensions {
  width: number;
  height: number;
}

export interface CompressedImagePlan {
  originalSizeBytes: number;
  targetMaxSizeBytes: number;
  recommendedQuality: number; // 0.0 - 1.0
  targetDimensions: ImageDimensions;
  needsCompression: boolean;
}

/**
 * Calculates optimal compression scale and quality to fit under target size limit (default: 500KB).
 */
export function planImageCompression(
  originalSizeBytes: number,
  dimensions: ImageDimensions,
  targetMaxBytes: number = 500 * 1024 // 500 KB default
): CompressedImagePlan {
  if (originalSizeBytes <= targetMaxBytes && dimensions.width <= 1920 && dimensions.height <= 1920) {
    return {
      originalSizeBytes,
      targetMaxSizeBytes: targetMaxBytes,
      recommendedQuality: 1.0,
      targetDimensions: dimensions,
      needsCompression: false,
    };
  }

  // Calculate downscaling ratio keeping aspect ratio
  const maxDimension = 1920; // 1080p equivalent
  let { width, height } = dimensions;

  if (width > maxDimension || height > maxDimension) {
    if (width > height) {
      height = Math.round((height * maxDimension) / width);
      width = maxDimension;
    } else {
      width = Math.round((width * maxDimension) / height);
      height = maxDimension;
    }
  }

  // Determine quality ratio
  const ratio = targetMaxBytes / originalSizeBytes;
  let recommendedQuality = 0.8;
  if (ratio < 0.25) {
    recommendedQuality = 0.6;
  } else if (ratio < 0.5) {
    recommendedQuality = 0.7;
  }

  return {
    originalSizeBytes,
    targetMaxSizeBytes: targetMaxBytes,
    recommendedQuality,
    targetDimensions: { width, height },
    needsCompression: true,
  };
}

/**
 * Validates whether an image payload size and MIME type comply with banking eKYC requirements.
 */
export function validateImageUploadPayload(
  sizeBytes: number,
  mimeType: string,
  maxSizeBytes: number = 5 * 1024 * 1024 // 5 MB max
): { isValid: boolean; error?: string } {
  const allowedMimes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp'];

  if (!allowedMimes.includes(mimeType.toLowerCase())) {
    return {
      isValid: false,
      error: `Unsupported image format: ${mimeType}. Allowed formats: JPEG, PNG, WEBP.`,
    };
  }

  if (sizeBytes > maxSizeBytes) {
    const mb = (maxSizeBytes / (1024 * 1024)).toFixed(0);
    return {
      isValid: false,
      error: `File size exceeds the maximum allowed limit of ${mb}MB.`,
    };
  }

  return { isValid: true };
}
