import { executeBiometric, type BiometricRequest, type BiometricResponse } from 'react-native-bizmob-plugin';
import { appLogger } from '../logger/AppLogger';

export interface BiometricPluginAdapter {
  executeBiometric: typeof executeBiometric;
}

const defaultBiometricAdapter: BiometricPluginAdapter = {
  executeBiometric,
};

export type BiometricHardwareType = 'FINGERPRINT' | 'FACE_ID' | 'NONE';

export interface BiometricCheckResult {
  isAvailable: boolean;
  biometricType: BiometricHardwareType;
  error?: string;
}

export interface BiometricAuthResult {
  success: boolean;
  errorCode?: string;
  errorMessage?: string;
}

/**
 * Biometric Authentication Service (`BiometricAuthService`)
 *
 * Wraps native Fingerprint and FaceID capabilities for:
 * - Quick PIN/Biometric App Unlock
 * - Sensitive step-up authorizations (high-value loan disbursement approval)
 */
export class BiometricAuthService {
  private static instance: BiometricAuthService;
  private adapter: BiometricPluginAdapter;

  constructor(adapter: BiometricPluginAdapter = defaultBiometricAdapter) {
    this.adapter = adapter;
  }

  public static getInstance(): BiometricAuthService {
    if (!BiometricAuthService.instance) {
      BiometricAuthService.instance = new BiometricAuthService();
    }
    return BiometricAuthService.instance;
  }

  /**
   * Checks if biometric hardware is present, enrolled, and ready on the device.
   */
  public async checkAvailability(): Promise<BiometricCheckResult> {
    try {
      const res: BiometricResponse = await this.adapter.executeBiometric({
        type: 'available',
      });

      const isAvailable = res.header.result && res.body.result === true;
      const rawType = res.body.type || 'NONE';
      let biometricType: BiometricHardwareType = 'NONE';

      if (rawType.includes('FINGERPRINT') || rawType === 'FINGERPRINT') {
        biometricType = 'FINGERPRINT';
      } else if (rawType.includes('FACE') || rawType === 'FACE_ID') {
        biometricType = 'FACE_ID';
      }

      return {
        isAvailable,
        biometricType,
        error: isAvailable ? undefined : res.header.error_text || res.body.errorMessage,
      };
    } catch (err: any) {
      appLogger.w('BiometricAuthService', '⚠️ Availability check failed:', err);
      return {
        isAvailable: false,
        biometricType: 'NONE',
        error: err?.message || 'Biometric check failed',
      };
    }
  }

  /**
   * Prompts the native OS biometric challenge dialog (TouchID / FaceID / Fingerprint).
   */
  public async authenticate(options?: {
    title?: string;
    subTitle?: string;
    cancelText?: string;
  }): Promise<BiometricAuthResult> {
    try {
      const res: BiometricResponse = await this.adapter.executeBiometric({
        type: 'auth',
        title: options?.title || 'Biometric Authentication',
        subTitle: options?.subTitle || 'Please authenticate to proceed',
        cancelText: options?.cancelText || 'Cancel',
      });

      const success = res.header.result && res.body.result === true;
      return {
        success,
        errorCode: success ? undefined : res.header.error_code || res.body.errorCode,
        errorMessage: success ? undefined : res.header.error_text || res.body.errorMessage,
      };
    } catch (err: any) {
      return {
        success: false,
        errorCode: 'E500',
        errorMessage: err?.message || 'Biometric authentication failed',
      };
    }
  }
}

export const defaultBiometricAuthService = BiometricAuthService.getInstance();
