/**
 * Unified Environment Configuration Module (`@mfe/core`)
 * 
 * Provides type-safe access to runtime environment variables across
 * SIT, UAT, and PROD flavors with fallback defaults.
 */

export type AppEnvironment = 'sit' | 'uat' | 'prod';

export interface AppEnvConfig {
  appEnv: AppEnvironment;
  appName: string;
  applicationId: string;
  bundleIdentifier: string;
  apiBaseUrl: string;
  enableMock: boolean;
  enableLogger: boolean;
  logLevel: 'DEBUG' | 'INFO' | 'WARN' | 'ERROR';
  otaManifestUrl: string;
  otaDownloadBaseUrl: string;
}

// Preset defaults for environments
const ENV_PRESETS: Record<AppEnvironment, AppEnvConfig> = {
  sit: {
    appEnv: 'sit',
    appName: '[SIT] MCNC React Native',
    applicationId: 'mcnc.mobile.reactnative.base.sit',
    bundleIdentifier: 'mcnc.mobile.reactnative.base.sit',
    apiBaseUrl: 'https://sit-api.mcnc.com.kh/los-app/api',
    enableMock: false,
    enableLogger: true,
    logLevel: 'DEBUG',
    otaManifestUrl: 'https://raw.githubusercontent.com/pangphannarupp/react-native-bundles/refs/heads/main/android/manifest.json',
    otaDownloadBaseUrl: 'https://raw.githubusercontent.com/pangphannarupp/react-native-bundles/refs/heads/main/android',
  },
  uat: {
    appEnv: 'uat',
    appName: '[UAT] MCNC React Native',
    applicationId: 'mcnc.mobile.reactnative.base.uat',
    bundleIdentifier: 'mcnc.mobile.reactnative.base.uat',
    apiBaseUrl: 'https://uat-api.mcnc.com.kh/los-app/api',
    enableMock: false,
    enableLogger: true,
    logLevel: 'INFO',
    otaManifestUrl: 'https://raw.githubusercontent.com/pangphannarupp/react-native-bundles/refs/heads/main/android/manifest.json',
    otaDownloadBaseUrl: 'https://raw.githubusercontent.com/pangphannarupp/react-native-bundles/refs/heads/main/android',
  },
  prod: {
    appEnv: 'prod',
    appName: 'MCNC React Native',
    applicationId: 'mcnc.mobile.reactnative.base',
    bundleIdentifier: 'mcnc.mobile.reactnative.base',
    apiBaseUrl: 'https://api.mcnc.com.kh/los-app/api',
    enableMock: false,
    enableLogger: false,
    logLevel: 'WARN',
    otaManifestUrl: 'https://raw.githubusercontent.com/pangphannarupp/react-native-bundles/refs/heads/main/android/manifest.json',
    otaDownloadBaseUrl: 'https://raw.githubusercontent.com/pangphannarupp/react-native-bundles/refs/heads/main/android',
  },
};

/**
 * Resolves active environment configuration.
 * Fallbacks to SIT in development.
 */
function resolveActiveConfig(): AppEnvConfig {
  const envKey = (
    (typeof process !== 'undefined' && process.env && process.env.APP_ENV) ||
    'sit'
  ).toLowerCase() as AppEnvironment;

  const baseConfig = ENV_PRESETS[envKey] || ENV_PRESETS.sit;

  // Allow overrides from process.env if injected by bundler or CLI
  if (typeof process !== 'undefined' && process.env) {
    return {
      ...baseConfig,
      appName: process.env.APP_NAME || baseConfig.appName,
      applicationId: process.env.APPLICATION_ID || baseConfig.applicationId,
      apiBaseUrl: process.env.API_BASE_URL || baseConfig.apiBaseUrl,
      enableMock: process.env.ENABLE_MOCK !== undefined 
        ? process.env.ENABLE_MOCK === 'true' 
        : baseConfig.enableMock,
      enableLogger: process.env.ENABLE_LOGGER !== undefined 
        ? process.env.ENABLE_LOGGER === 'true' 
        : baseConfig.enableLogger,
      otaManifestUrl: process.env.OTA_MANIFEST_URL || baseConfig.otaManifestUrl,
      otaDownloadBaseUrl: process.env.OTA_DOWNLOAD_BASE_URL || baseConfig.otaDownloadBaseUrl,
    };
  }

  return baseConfig;
}

export class ConfigService {
  private static activeConfig: AppEnvConfig = resolveActiveConfig();

  public static get(): AppEnvConfig {
    return ConfigService.activeConfig;
  }

  public static setEnvironment(env: AppEnvironment): void {
    ConfigService.activeConfig = {
      ...ENV_PRESETS[env],
    };
  }

  public static isSIT(): boolean {
    return ConfigService.activeConfig.appEnv === 'sit';
  }

  public static isUAT(): boolean {
    return ConfigService.activeConfig.appEnv === 'uat';
  }

  public static isProd(): boolean {
    return ConfigService.activeConfig.appEnv === 'prod';
  }
}

export const AppConfig = ConfigService.get();
