/**
 * TaxAndSalaryUtil: Calculates Vietnamese Personal Income Tax (PIT / Thuế TNCN),
 * progressive tax brackets, gross-to-net salary deductions, and Enterprise Tax Code (MST) validation.
 * Aligned with Lotte Finance underwriting income verification (DOC110/DOC117/DOC120).
 */

export interface SalaryBreakdown {
  grossSalary: number;
  socialInsurance: number; // 8%
  healthInsurance: number; // 1.5%
  unemploymentInsurance: number; // 1%
  totalInsuranceDeductions: number;
  personalDeduction: number; // 11M VND
  dependentDeduction: number; // 4.4M VND per dependent
  taxableIncome: number;
  personalIncomeTax: number;
  netSalary: number;
}

export class TaxAndSalaryUtil {
  // Statutory insurance rates in Vietnam
  public static readonly SOCIAL_INSURANCE_RATE = 0.08; // 8% BHXH
  public static readonly HEALTH_INSURANCE_RATE = 0.015; // 1.5% BHYT
  public static readonly UNEMPLOYMENT_INSURANCE_RATE = 0.01; // 1% BHTN

  // Personal tax deductions (VND)
  public static readonly PERSONAL_RELIEF = 11_000_000;
  public static readonly DEPENDENT_RELIEF = 4_400_000;

  /**
   * Calculates progressive Personal Income Tax (PIT) according to statutory tax brackets:
   * Level 1: Up to 5M VND -> 5%
   * Level 2: 5M to 10M VND -> 10%
   * Level 3: 10M to 18M VND -> 15%
   * Level 4: 18M to 32M VND -> 20%
   * Level 5: 32M to 52M VND -> 25%
   * Level 6: 52M to 80M VND -> 30%
   * Level 7: Over 80M VND -> 35%
   */
  public static calculateProgressivePit(taxableIncome: number): number {
    if (taxableIncome <= 0) return 0;

    let remaining = taxableIncome;
    let tax = 0;

    const brackets = [
      { limit: 5_000_000, rate: 0.05 },
      { limit: 5_000_000, rate: 0.10 }, // 5M to 10M
      { limit: 8_000_000, rate: 0.15 }, // 10M to 18M
      { limit: 14_000_000, rate: 0.20 }, // 18M to 32M
      { limit: 20_000_000, rate: 0.25 }, // 32M to 52M
      { limit: 28_000_000, rate: 0.30 }, // 52M to 80M
      { limit: Infinity, rate: 0.35 }, // Over 80M
    ];

    for (const b of brackets) {
      if (remaining <= 0) break;
      const taxableSlice = Math.min(remaining, b.limit);
      tax += taxableSlice * b.rate;
      remaining -= taxableSlice;
    }

    return Math.round(tax);
  }

  /**
   * Calculates comprehensive Gross-to-Net salary breakdown.
   */
  public static calculateGrossToNet(
    grossSalary: number,
    numberOfDependents: number = 0
  ): SalaryBreakdown {
    const gross = Math.max(0, grossSalary);

    const socialInsurance = Math.round(gross * this.SOCIAL_INSURANCE_RATE);
    const healthInsurance = Math.round(gross * this.HEALTH_INSURANCE_RATE);
    const unemploymentInsurance = Math.round(gross * this.UNEMPLOYMENT_INSURANCE_RATE);
    const totalInsuranceDeductions =
      socialInsurance + healthInsurance + unemploymentInsurance;

    const personalDeduction = this.PERSONAL_RELIEF;
    const dependentDeduction = numberOfDependents * this.DEPENDENT_RELIEF;

    const incomeBeforeTax = gross - totalInsuranceDeductions;
    const taxableIncome = Math.max(
      0,
      incomeBeforeTax - personalDeduction - dependentDeduction
    );

    const personalIncomeTax = this.calculateProgressivePit(taxableIncome);
    const netSalary = gross - totalInsuranceDeductions - personalIncomeTax;

    return {
      grossSalary: gross,
      socialInsurance,
      healthInsurance,
      unemploymentInsurance,
      totalInsuranceDeductions,
      personalDeduction,
      dependentDeduction,
      taxableIncome,
      personalIncomeTax,
      netSalary,
    };
  }

  /**
   * Validates Vietnamese Enterprise Tax Code / Personal Tax ID (Mã số thuế - MST):
   * Pattern: 10 digits or 13 digits (with branch suffix e.g. 0103172804 or 0103172804-001).
   */
  public static isValidTaxId(taxId: string): boolean {
    if (!taxId) return false;
    const clean = taxId.trim().replace(/\s+/g, '');
    return /^\d{10}$|^\d{10}-\d{3}$|^\d{13}$/.test(clean);
  }
}

