/**
 * Geolocation & Proximity Distance Utilities
 *
 * Implements the Haversine great-circle formula, boundary geofencing,
 * and user-friendly distance formatting for officer site visits
 * and debtor collection maps.
 */

export interface GeoCoordinates {
  latitude: number;
  longitude: number;
}

export interface GeofenceCheckResult {
  isWithinFence: boolean;
  actualDistanceKm: number;
  radiusKm: number;
}

/**
 * Calculates the great-circle distance between two GPS coordinates in kilometers
 * using the Haversine formula.
 */
export function calculateDistanceKm(
  coord1: GeoCoordinates,
  coord2: GeoCoordinates
): number {
  const EARTH_RADIUS_KM = 6371;

  const lat1Rad = (coord1.latitude * Math.PI) / 180;
  const lat2Rad = (coord2.latitude * Math.PI) / 180;
  const deltaLat = ((coord2.latitude - coord1.latitude) * Math.PI) / 180;
  const deltaLon = ((coord2.longitude - coord1.longitude) * Math.PI) / 180;

  const a =
    Math.sin(deltaLat / 2) * Math.sin(deltaLat / 2) +
    Math.cos(lat1Rad) *
      Math.cos(lat2Rad) *
      Math.sin(deltaLon / 2) *
      Math.sin(deltaLon / 2);

  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));

  return EARTH_RADIUS_KM * c;
}

/**
 * Verifies if an officer's current position is within an approved customer site geofence radius.
 */
export function checkGeofence(
  officerPos: GeoCoordinates,
  targetPos: GeoCoordinates,
  radiusKm: number = 0.5 // Default 500 meters
): GeofenceCheckResult {
  const distance = calculateDistanceKm(officerPos, targetPos);
  return {
    isWithinFence: distance <= radiusKm,
    actualDistanceKm: Math.round(distance * 100) / 100,
    radiusKm,
  };
}

/**
 * Formats a metric distance into clean localized text:
 * - `< 1 km` -> `XXX m`
 * - `>= 1 km` -> `X.X km`
 */
export function formatDistance(distanceKm: number): string {
  if (isNaN(distanceKm) || distanceKm < 0) return '0 m';

  if (distanceKm < 1) {
    const meters = Math.round(distanceKm * 1000);
    return `${meters} m`;
  }

  return `${distanceKm.toFixed(1)} km`;
}
