import {
  disableScreenshot as nativeDisableScreenshot,
  enableScreenshot as nativeEnableScreenshot,
  registerScreenshotListener as nativeRegisterScreenshotListener,
  unregisterScreenshotListener as nativeUnregisterScreenshotListener,
  addScreenshotListener as nativeAddScreenshotListener,
  type ScreenshotEvent,
} from 'react-native-bizmob-plugin';
import { appLogger } from '../logger/AppLogger';

export interface ScreenshotPluginAdapter {
  disableScreenshot: typeof nativeDisableScreenshot;
  enableScreenshot: typeof nativeEnableScreenshot;
  registerScreenshotListener: typeof nativeRegisterScreenshotListener;
  unregisterScreenshotListener: typeof nativeUnregisterScreenshotListener;
  addScreenshotListener: typeof nativeAddScreenshotListener;
}

const defaultAdapter: ScreenshotPluginAdapter = {
  disableScreenshot: nativeDisableScreenshot,
  enableScreenshot: nativeEnableScreenshot,
  registerScreenshotListener: nativeRegisterScreenshotListener,
  unregisterScreenshotListener: nativeUnregisterScreenshotListener,
  addScreenshotListener: nativeAddScreenshotListener,
};

export type ScreenshotListener = (event: ScreenshotEvent) => void;

/**
 * Screen Security & Anti-Screenshot Service (`ScreenSecurityService`)
 *
 * Enforces banking data protection regulations:
 * - Prevents screenshots on Android (FLAG_SECURE) and iOS (window shield).
 * - Detects user screenshot capture attempts and emits telemetry.
 */
export class ScreenSecurityService {
  private static instance: ScreenSecurityService;
  private adapter: ScreenshotPluginAdapter;
  private isProtectionEnabled = false;
  private listeners: Set<ScreenshotListener> = new Set();
  private subscription: { remove: () => void } | null = null;

  constructor(adapter: ScreenshotPluginAdapter = defaultAdapter) {
    this.adapter = adapter;
  }

  public static getInstance(): ScreenSecurityService {
    if (!ScreenSecurityService.instance) {
      ScreenSecurityService.instance = new ScreenSecurityService();
    }
    return ScreenSecurityService.instance;
  }

  /**
   * Disables screenshots and blanks out the app thumbnail in the task switcher.
   */
  public async enableProtection(): Promise<boolean> {
    try {
      const res = await this.adapter.disableScreenshot();
      this.isProtectionEnabled = res?.header?.result ?? true;
      appLogger.i('ScreenSecurityService', '🛡️ Screen capture protection ENABLED.');
      return this.isProtectionEnabled;
    } catch (err) {
      appLogger.w('ScreenSecurityService', '⚠️ Failed to enable screen protection:', err);
      return false;
    }
  }

  /**
   * Re-enables screenshotting (used for non-sensitive public views e.g. branch locator).
   */
  public async disableProtection(): Promise<boolean> {
    try {
      const res = await this.adapter.enableScreenshot();
      this.isProtectionEnabled = !(res?.header?.result ?? true);
      appLogger.i('ScreenSecurityService', '🔓 Screen capture protection DISABLED.');
      return !this.isProtectionEnabled;
    } catch (err) {
      appLogger.w('ScreenSecurityService', '⚠️ Failed to disable screen protection:', err);
      return false;
    }
  }

  public getIsProtectionEnabled(): boolean {
    return this.isProtectionEnabled;
  }

  /**
   * Subscribes to screenshot capture detection events.
   */
  public onScreenshotTaken(listener: ScreenshotListener): () => void {
    this.listeners.add(listener);

    if (!this.subscription) {
      try {
        this.adapter.registerScreenshotListener();
      } catch {}
      this.subscription = this.adapter.addScreenshotListener((evt) => {
        appLogger.w('ScreenSecurityService', '📸 Screenshot event detected:', evt);
        for (const cb of Array.from(this.listeners)) {
          try {
            cb(evt);
          } catch {}
        }
      });
    }

    return () => {
      this.listeners.delete(listener);
      if (this.listeners.size === 0 && this.subscription) {
        this.subscription.remove();
        this.subscription = null;
        try {
          this.adapter.unregisterScreenshotListener();
        } catch {}
      }
    };
  }
}

export const defaultScreenSecurityService = ScreenSecurityService.getInstance();
