/**
 * Timing & Rate-Limiting Utilities
 *
 * Implements lightweight, robust `debounce` and `throttle`
 * suitable for React Native UI inputs, search fields, sliders,
 * and high-frequency network or scroll handlers.
 */

export interface DebounceOptions {
  leading?: boolean;
  trailing?: boolean;
  maxWait?: number;
}

export interface DebouncedFunction<TArgs extends any[]> {
  (...args: TArgs): void;
  cancel(): void;
  flush(): void;
}

/**
 * Creates a debounced function that delays invoking `fn` until after `delayMs`
 * milliseconds have elapsed since the last time the debounced function was invoked.
 */
export function debounce<TArgs extends any[]>(
  fn: (...args: TArgs) => void,
  delayMs: number = 300,
  options: DebounceOptions = { leading: false, trailing: true }
): DebouncedFunction<TArgs> {
  let timerId: ReturnType<typeof setTimeout> | null = null;
  let lastArgs: TArgs | null = null;
  let lastCallTime: number | null = null;

  const invoke = () => {
    if (lastArgs) {
      fn(...lastArgs);
      lastArgs = null;
    }
    timerId = null;
  };

  const debounced = (...args: TArgs) => {
    lastArgs = args;
    const now = Date.now();
    const isFirstCall = lastCallTime === null;
    lastCallTime = now;

    if (isFirstCall && options.leading) {
      invoke();
      return;
    }

    if (timerId !== null) {
      clearTimeout(timerId);
    }

    if (options.trailing !== false) {
      timerId = setTimeout(invoke, delayMs);
    }
  };

  debounced.cancel = () => {
    if (timerId !== null) {
      clearTimeout(timerId);
      timerId = null;
    }
    lastArgs = null;
    lastCallTime = null;
  };

  debounced.flush = () => {
    if (timerId !== null) {
      clearTimeout(timerId);
      invoke();
    }
  };

  return debounced;
}

export interface ThrottledFunction<TArgs extends any[]> {
  (...args: TArgs): void;
  cancel(): void;
}

/**
 * Creates a throttled function that only invokes `fn` at most once per
 * every `intervalMs` milliseconds.
 */
export function throttle<TArgs extends any[]>(
  fn: (...args: TArgs) => void,
  intervalMs: number = 250
): ThrottledFunction<TArgs> {
  let lastExecTime = 0;
  let timerId: ReturnType<typeof setTimeout> | null = null;
  let savedArgs: TArgs | null = null;

  const throttled = (...args: TArgs) => {
    const now = Date.now();
    const elapsed = now - lastExecTime;
    savedArgs = args;

    if (elapsed >= intervalMs) {
      if (timerId !== null) {
        clearTimeout(timerId);
        timerId = null;
      }
      lastExecTime = now;
      fn(...savedArgs);
      savedArgs = null;
    } else if (timerId === null) {
      timerId = setTimeout(() => {
        lastExecTime = Date.now();
        timerId = null;
        if (savedArgs) {
          fn(...savedArgs);
          savedArgs = null;
        }
      }, intervalMs - elapsed);
    }
  };

  throttled.cancel = () => {
    if (timerId !== null) {
      clearTimeout(timerId);
      timerId = null;
    }
    savedArgs = null;
    lastExecTime = 0;
  };

  return throttled;
}
